CREATE OR REPLACE FUNCTION public.accept_invite(p_token text, p_username text, p_password text, p_full_name text, p_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invite     public.user_invites;
  v_username   text := lower(trim(coalesce(p_username, '')));
  v_full_name  text := trim(coalesce(p_full_name, ''));
  v_email      text;
  v_contact_id uuid;
  v_matched    boolean := false;
  new_user_id  uuid := gen_random_uuid();
  encrypted_pw text;
BEGIN
  -- The token IS the authorization: single-use, unexpired, unrevoked.
  SELECT * INTO v_invite FROM public.user_invites WHERE token = p_token FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'This invite link is not valid';
  END IF;
  IF v_invite.status = 'accepted' THEN
    RAISE EXCEPTION 'This invite has already been used';
  END IF;
  IF v_invite.status <> 'pending' THEN
    RAISE EXCEPTION 'This invite is no longer active — ask your administrator for a new one';
  END IF;
  IF v_invite.expires_at <= now() THEN
    RAISE EXCEPTION 'This invite has expired — ask your administrator for a new one';
  END IF;

  -- The invite's email is binding when set; phone-only invites collect one here.
  v_email := lower(coalesce(nullif(v_invite.email, ''), nullif(trim(coalesce(p_email, '')), '')));
  IF v_email IS NULL OR v_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RAISE EXCEPTION 'A valid email address is required';
  END IF;
  IF v_full_name = '' THEN
    RAISE EXCEPTION 'Your full name is required';
  END IF;
  IF v_username !~ '^[a-z0-9][a-z0-9._-]{2,31}$' THEN
    RAISE EXCEPTION 'Username must be 3-32 characters: letters, numbers, dots, dashes';
  END IF;
  IF length(coalesce(p_password, '')) < 6 THEN
    RAISE EXCEPTION 'Password must be at least 6 characters';
  END IF;

  -- ── NEW: adopt the person record this invite belongs to, if it exists. ──
  -- Oldest match wins, so a register imported before any hand-created stub is
  -- the one that gains the login.
  SELECT id INTO v_contact_id
  FROM public.contacts
  WHERE lower(email) = v_email
  ORDER BY created_at NULLS LAST
  LIMIT 1;

  v_matched := v_contact_id IS NOT NULL;
  IF NOT v_matched THEN
    v_contact_id := gen_random_uuid();
  END IF;

  -- Collision checks across every namespace a login can resolve through.
  IF EXISTS (SELECT 1 FROM auth.users WHERE lower(email) IN (v_email, v_username || '@cainergy.com')) THEN
    RAISE EXCEPTION 'An account already exists for this email or username';
  END IF;
  IF EXISTS (SELECT 1 FROM public.users WHERE lower(username) = v_username) THEN
    RAISE EXCEPTION 'Username "%" is already taken', v_username;
  END IF;
  -- The adopted contact is allowed to own the code being claimed.
  IF EXISTS (
    SELECT 1 FROM public.contacts
    WHERE lower(code) = v_username AND (NOT v_matched OR id <> v_contact_id)
  ) THEN
    RAISE EXCEPTION 'Username "%" is already taken', v_username;
  END IF;

  -- 1. The person record — adopt or create.
  IF v_matched THEN
    -- Keep the imported code, department, rate and qualifications; grant access
    -- and fill only what the register could not know.
    UPDATE public.contacts SET
      name                = COALESCE(NULLIF(v_full_name, ''), name),
      phone               = COALESCE(NULLIF(v_invite.phone, ''), phone),
      roles               = CASE
                              WHEN roles IS NULL OR roles = '{}' THEN ARRAY[v_invite.role]
                              WHEN v_invite.role = ANY(roles) THEN roles
                              ELSE array_append(roles, v_invite.role)
                            END,
      is_active           = true,
      can_login           = true,
      can_submit_requests = true,
      can_log_time        = true
    WHERE id = v_contact_id;
  ELSE
    INSERT INTO public.contacts (
      id, code, name, email, phone, title, roles,
      is_active, is_employee, can_login, can_submit_requests, can_log_time
    ) VALUES (
      v_contact_id, v_username, v_full_name, v_email, v_invite.phone, NULL,
      ARRAY[v_invite.role], true, true, true, true, true
    );
  END IF;

  -- 2. The auth account — registered under the invitee's REAL email.
  encrypted_pw := extensions.crypt(p_password, extensions.gen_salt('bf'));

  INSERT INTO auth.users (
    instance_id, id, aud, role, email, encrypted_password,
    email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
    created_at, updated_at,
    confirmation_token, email_change, email_change_token_new, recovery_token
  ) VALUES (
    '00000000-0000-0000-0000-000000000000',
    new_user_id, 'authenticated', 'authenticated',
    v_email, encrypted_pw, now(),
    '{"provider":"email","providers":["email"]}',
    json_build_object('username', v_username, 'role', v_invite.role,
                      'contact_id', v_contact_id, 'full_name', v_full_name),
    now(), now(), '', '', '', ''
  );

  INSERT INTO auth.identities (
    id, user_id, provider_id, identity_data, provider,
    last_sign_in_at, created_at, updated_at
  ) VALUES (
    gen_random_uuid(), new_user_id, new_user_id::text,
    jsonb_build_object('sub', new_user_id::text, 'email', v_email),
    'email', now(), now(), now()
  );

  -- 3. The app profile.
  INSERT INTO public.users (id, username, email, contact_id, status, roles)
  VALUES (new_user_id, v_username, v_email, v_contact_id, 'active',
          jsonb_build_array(v_invite.role))
  ON CONFLICT (id) DO UPDATE SET
    username   = EXCLUDED.username,
    email      = EXCLUDED.email,
    contact_id = EXCLUDED.contact_id,
    roles      = EXCLUDED.roles;

  -- 3b. Close the loop the other way: the contact now points at its login.
  UPDATE public.contacts SET user_id = new_user_id WHERE id = v_contact_id;

  -- 4. Burn the invite.
  UPDATE public.user_invites
  SET status = 'accepted', accepted_user_id = new_user_id,
      accepted_at = now(), updated_at = now()
  WHERE id = v_invite.id;

  RETURN jsonb_build_object(
    'user_id', new_user_id,
    'email', v_email,
    'contact_id', v_contact_id,
    'contact_linked', v_matched
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_reset_password(p_user_id uuid, p_new_password text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'Not authorized: administrators only'; END IF;
    IF length(coalesce(p_new_password,'')) < 8 THEN RAISE EXCEPTION 'Password must be at least 8 characters'; END IF;
    UPDATE auth.users
    SET encrypted_password = extensions.crypt(p_new_password, extensions.gen_salt('bf')), updated_at = now()
    WHERE id = p_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'User not found'; END IF;
END; $function$
;

CREATE OR REPLACE FUNCTION public.caller_can(p_module text, p_action text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH me AS (
        SELECT u.roles ->> 0 AS role,
               coalesce(u.permission_overrides, '{}'::jsonb) AS overrides
        FROM public.users u
        WHERE (
                lower(coalesce(u.email, '')) = lower(coalesce(auth.jwt() ->> 'email', ''))
             OR lower(coalesce(u.username, '')) = lower(split_part(coalesce(auth.jwt() ->> 'email', ''), '@', 1))
              )
          AND coalesce(u.status, 'active') = 'active'
        LIMIT 1
    )
    -- No matching row → role is NULL → role_can falls back to __default__
    -- (BASE_PACKAGE_DEFAULTS, fail-closed). Same posture AuthContext takes.
    SELECT public.role_can(
        (SELECT role FROM me),
        coalesce((SELECT overrides FROM me), '{}'::jsonb),
        p_module,
        p_action
    );
$function$
;

CREATE OR REPLACE FUNCTION public.caller_can_view_all_requests()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT public.is_admin()
        OR EXISTS (
            SELECT 1 FROM users u
            WHERE u.id = public.caller_user_id()
              AND coalesce(u.status, 'active') = 'active'
              AND u.roles ?| ARRAY['PLANNER','SUPERVISOR','MANAGER','EXECUTIVE','RELIABILITY_ENG']
        );
$function$
;

CREATE OR REPLACE FUNCTION public.caller_company()
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
    SELECT nullif(auth.jwt() -> 'app_metadata' ->> 'company_id', '')::uuid
$function$
;

CREATE OR REPLACE FUNCTION public.caller_user_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT u.id
    FROM users u
    WHERE u.id = auth.uid()
       OR lower(coalesce(u.email, ''))    = lower(coalesce(auth.jwt() ->> 'email', ''))
       OR lower(coalesce(u.username, '')) = lower(split_part(coalesce(auth.jwt() ->> 'email', ''), '@', 1))
    ORDER BY (u.id = auth.uid()) DESC   -- prefer the exact auth-id match
    LIMIT 1
$function$
;

CREATE OR REPLACE FUNCTION public.caller_work_centers()
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT coalesce(array_agg(m.work_center_id), '{}'::uuid[])
    FROM work_center_members m
    JOIN users u ON u.contact_id = m.contact_id
    WHERE u.id = public.caller_user_id()
$function$
;

CREATE OR REPLACE FUNCTION public.companies_tier_is_pinned()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
    -- Sessionless (service role / migrations): may change the tier.
    IF auth.uid() IS NULL THEN
        RETURN NEW;
    END IF;
    IF NEW.tier IS DISTINCT FROM OLD.tier THEN
        RAISE EXCEPTION 'tier is set by your plan, not by the application'
            USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.compute_oee(p_asset_id uuid DEFAULT NULL::uuid, p_from date DEFAULT (CURRENT_DATE - 30), p_to date DEFAULT CURRENT_DATE)
 RETURNS TABLE(asset_id uuid, asset_tag text, asset_name text, availability_pct numeric, performance_pct numeric, quality_pct numeric, oee_pct numeric, total_output numeric, good_output numeric, defect_count numeric, planned_hrs numeric, actual_hrs numeric, oee_target_pct numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    a.id                                                    AS asset_id,
    a.tag                                                   AS asset_tag,
    a.name                                                  AS asset_name,

    -- Availability = actual_run_time / planned_run_time × 100
    ROUND(
      CASE WHEN SUM(pl.planned_run_time_min) > 0
        THEN SUM(pl.actual_run_time_min) / SUM(pl.planned_run_time_min) * 100
        ELSE 0
      END, 1
    )                                                       AS availability_pct,

    -- Performance = (total_output × ideal_cycle_time_sec) / (actual_run_time_min × 60) × 100
    ROUND(
      CASE WHEN SUM(pl.actual_run_time_min) > 0 AND MAX(apc.ideal_cycle_time_sec) > 0
        THEN LEAST(100,
          (SUM(pl.total_output) * MAX(apc.ideal_cycle_time_sec))
          / (SUM(pl.actual_run_time_min) * 60) * 100
        )
        -- Fallback: if no cycle time configured, use capacity-based calculation
        WHEN SUM(pl.actual_run_time_min) > 0 AND MAX(apc.design_capacity_per_hr) > 0
        THEN LEAST(100,
          SUM(pl.total_output)
          / (SUM(pl.actual_run_time_min) / 60 * MAX(apc.design_capacity_per_hr)) * 100
        )
        ELSE 0
      END, 1
    )                                                       AS performance_pct,

    -- Quality = good_output / total_output × 100
    ROUND(
      CASE WHEN SUM(pl.total_output) > 0
        THEN SUM(pl.good_output) / SUM(pl.total_output) * 100
        ELSE 0
      END, 1
    )                                                       AS quality_pct,

    -- OEE = A × P × Q / 10000
    ROUND(
      CASE WHEN SUM(pl.planned_run_time_min) > 0
                AND SUM(pl.total_output) > 0
        THEN (
          (SUM(pl.actual_run_time_min) / SUM(pl.planned_run_time_min))
          * LEAST(1,
              CASE
                WHEN MAX(apc.ideal_cycle_time_sec) > 0
                  THEN (SUM(pl.total_output) * MAX(apc.ideal_cycle_time_sec))
                       / (SUM(pl.actual_run_time_min) * 60)
                WHEN MAX(apc.design_capacity_per_hr) > 0
                  THEN SUM(pl.total_output)
                       / (SUM(pl.actual_run_time_min) / 60 * MAX(apc.design_capacity_per_hr))
                ELSE 0
              END
          )
          * (SUM(pl.good_output) / SUM(pl.total_output))
          * 100
        )
        ELSE 0
      END, 1
    )                                                       AS oee_pct,

    COALESCE(SUM(pl.total_output), 0)                       AS total_output,
    COALESCE(SUM(pl.good_output), 0)                        AS good_output,
    COALESCE(SUM(pl.defect_count), 0)                       AS defect_count,
    ROUND(COALESCE(SUM(pl.planned_run_time_min), 0) / 60, 1) AS planned_hrs,
    ROUND(COALESCE(SUM(pl.actual_run_time_min), 0) / 60, 1)  AS actual_hrs,
    COALESCE(MAX(apc.oee_target_pct), 85)                    AS oee_target_pct

  FROM assets a
  JOIN production_logs pl ON pl.asset_id = a.id
  LEFT JOIN asset_production_config apc ON apc.asset_id = a.id
  WHERE pl.shift_date BETWEEN p_from AND p_to
    AND (p_asset_id IS NULL OR a.id = p_asset_id)
  GROUP BY a.id, a.tag, a.name
  ORDER BY oee_pct ASC;  -- Worst performers first
$function$
;

CREATE OR REPLACE FUNCTION public.create_auth_user(p_email text, p_password text, p_username text, p_role text, p_contact_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  new_user_id uuid;
  encrypted_pw text;
BEGIN
  -- Only administrators may provision accounts (0181).
  IF auth.uid() IS NOT NULL AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized: administrators only';
  END IF;

  new_user_id := gen_random_uuid();
  encrypted_pw := extensions.crypt(p_password, extensions.gen_salt('bf'));

  INSERT INTO auth.users (
    instance_id, id, aud, role, email, encrypted_password,
    email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
    created_at, updated_at,
    confirmation_token, email_change, email_change_token_new, recovery_token
  ) VALUES (
    '00000000-0000-0000-0000-000000000000',
    new_user_id, 'authenticated', 'authenticated',
    p_email, encrypted_pw, now(),
    '{"provider":"email","providers":["email"]}',
    json_build_object('username', p_username, 'role', p_role, 'contact_id', p_contact_id),
    now(), now(), '', '', '', ''
  );

  INSERT INTO auth.identities (
    id, user_id, provider_id, identity_data, provider,
    last_sign_in_at, created_at, updated_at
  ) VALUES (
    gen_random_uuid(), new_user_id, new_user_id::text,
    jsonb_build_object('sub', new_user_id::text, 'email', p_email),
    'email', now(), now(), now()
  );

  -- The link: app-user profile tying this login to its person (contact_id).
  INSERT INTO public.users (id, username, email, contact_id, status, roles)
  VALUES (new_user_id, p_username, p_email, p_contact_id, 'active',
          jsonb_build_array(coalesce(p_role, 'GUEST')))
  ON CONFLICT (id) DO UPDATE SET
    username   = EXCLUDED.username,
    email      = EXCLUDED.email,
    contact_id = EXCLUDED.contact_id,
    roles      = EXCLUDED.roles;

  RETURN new_user_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_user_invite(p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_role text DEFAULT 'TECHNICIAN'::text, p_expires_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_email text := lower(nullif(trim(coalesce(p_email, '')), ''));
  v_phone text := nullif(trim(coalesce(p_phone, '')), '');
  v_invite public.user_invites;
BEGIN
  -- Only administrators may invite (same guard as create_auth_user / 0181).
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized: administrators only';
  END IF;

  IF v_email IS NULL AND v_phone IS NULL THEN
    RAISE EXCEPTION 'Provide an email address or a phone number';
  END IF;
  IF v_email IS NOT NULL AND v_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RAISE EXCEPTION 'Invalid email address: %', v_email;
  END IF;
  -- SUPER_ADMIN is deliberately not invitable — promote explicitly instead.
  IF p_role NOT IN ('TECHNICIAN','REQUESTER','PLANNER','SUPERVISOR',
                    'RELIABILITY_ENG','MANAGER','EXECUTIVE','SYS_ADMIN','INTERNAL') THEN
    RAISE EXCEPTION 'Invalid role: %', p_role;
  END IF;
  -- One live invite per email — surface the existing one instead of stacking.
  IF v_email IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.user_invites
    WHERE lower(email) = v_email AND status = 'pending' AND expires_at > now()
  ) THEN
    RAISE EXCEPTION 'A pending invite already exists for % — revoke it first to reissue', v_email;
  END IF;

  INSERT INTO public.user_invites (token, email, phone, invited_name, role, invited_by, expires_at)
  VALUES (
    replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''),
    v_email, v_phone, nullif(trim(coalesce(p_name, '')), ''), p_role, auth.uid(),
    now() + make_interval(days => greatest(1, least(coalesce(p_expires_days, 7), 30)))
  )
  RETURNING * INTO v_invite;

  RETURN jsonb_build_object(
    'id', v_invite.id, 'token', v_invite.token, 'email', v_invite.email,
    'phone', v_invite.phone, 'invited_name', v_invite.invited_name,
    'role', v_invite.role, 'expires_at', v_invite.expires_at
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.custom_access_token_hook(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_company uuid;
    v_claims  jsonb;
BEGIN
    SELECT u.company_id INTO v_company
      FROM public.users u
     WHERE u.id = (event ->> 'user_id')::uuid;

    v_claims := coalesce(event -> 'claims', '{}'::jsonb);

    IF v_company IS NOT NULL THEN
        -- app_metadata may be absent on a fresh claim set; create it first.
        IF v_claims -> 'app_metadata' IS NULL THEN
            v_claims := jsonb_set(v_claims, '{app_metadata}', '{}'::jsonb);
        END IF;
        v_claims := jsonb_set(v_claims, '{app_metadata,company_id}', to_jsonb(v_company::text));
    END IF;

    RETURN jsonb_set(event, '{claims}', v_claims);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_auth_user(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$ BEGIN DELETE FROM auth.users WHERE id = p_user_id; END; $function$
;

CREATE OR REPLACE FUNCTION public.deprovision_tenant(p_company uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_origin    uuid;
    t           record;
    v_pass      int := 0;
    v_deleted   int;
    v_progress  boolean := true;
BEGIN
    SELECT id INTO v_origin FROM public.companies WHERE active IS TRUE ORDER BY created_at ASC LIMIT 1;
    IF p_company = v_origin THEN
        RAISE EXCEPTION 'deprovision_tenant: refusing to destroy the origin company';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.companies WHERE id = p_company) THEN
        RAISE EXCEPTION 'deprovision_tenant: company % does not exist', p_company;
    END IF;

    -- Auth first: identities cascade from auth.users (verified 'c'), and
    -- public.users carries the company FK.
    DELETE FROM auth.users   WHERE id IN (SELECT id FROM public.users WHERE company_id = p_company);
    DELETE FROM public.users WHERE company_id = p_company;

    -- Sweep every tenant-owned table. FKs between them (work_orders → assets…)
    -- make single-pass ordering fragile, so loop until a pass deletes nothing.
    WHILE v_progress AND v_pass < 6 LOOP
        v_progress := false;
        v_pass := v_pass + 1;
        FOR t IN
            SELECT c.relname FROM pg_class c
            JOIN pg_namespace n ON n.oid = c.relnamespace
            WHERE n.nspname = 'public' AND c.relkind = 'r'
              AND c.relname NOT IN ('companies', 'users')
              AND EXISTS (SELECT 1 FROM information_schema.columns col
                           WHERE col.table_schema = 'public'
                             AND col.table_name = c.relname
                             AND col.column_name = 'company_id')
        LOOP
            BEGIN
                EXECUTE format('DELETE FROM public.%I WHERE company_id = $1', t.relname) USING p_company;
                GET DIAGNOSTICS v_deleted = ROW_COUNT;
                IF v_deleted > 0 THEN v_progress := true; END IF;
            EXCEPTION WHEN foreign_key_violation THEN
                v_progress := true;   -- children remain; a later pass clears them
            END;
        END LOOP;
    END LOOP;

    -- If anything still references the company, this DELETE raises a foreign
    -- key violation — loud and specific, which is exactly what we want. It only
    -- succeeds when the sweep genuinely got everything.
    DELETE FROM public.companies WHERE id = p_company;
END $function$
;

CREATE OR REPLACE FUNCTION public.ers_ai_budget_record(p_user_id uuid, p_tokens integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    UPDATE ers_ai_usage_daily u
       SET tokens = u.tokens + GREATEST(COALESCE(p_tokens, 0), 0),
           last_call_at = NOW()
     WHERE u.user_id = p_user_id
       AND u.usage_date = (NOW() AT TIME ZONE 'UTC')::DATE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_ai_budget_reserve(p_user_id uuid)
 RETURNS TABLE(allowed boolean, requests_today integer, tokens_today bigint, max_requests integer, max_tokens bigint, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_today   DATE := (NOW() AT TIME ZONE 'UTC')::DATE;
    v_max_req INTEGER;
    v_max_tok BIGINT;
    v_req     INTEGER;
    v_tok     BIGINT;
BEGIN
    -- A row keyed on the user's UUID wins over 'default'.
    SELECT p.max_requests_per_day, p.max_tokens_per_day
      INTO v_max_req, v_max_tok
      FROM ers_ai_budget_policy p
     WHERE p.id IN (p_user_id::TEXT, 'default')
     ORDER BY (p.id = 'default')   -- FALSE (the user's own row) sorts first
     LIMIT 1;

    -- No policy at all = fail open. A missing config row must not take the
    -- product offline; the ceiling is a cost guard, not a security control.
    IF v_max_req IS NULL THEN
        RETURN QUERY SELECT TRUE, 0, 0::BIGINT, 0, 0::BIGINT, 'no budget policy configured'::TEXT;
        RETURN;
    END IF;

    -- DO UPDATE rather than DO NOTHING: it always returns the row AND locks it
    -- for the rest of this transaction, which is what serialises the check and
    -- the increment below. DO NOTHING can leave a concurrently-inserted row
    -- invisible to our snapshot, which would read as "no usage yet".
    INSERT INTO ers_ai_usage_daily (user_id, usage_date)
    VALUES (p_user_id, v_today)
    ON CONFLICT (user_id, usage_date)
      DO UPDATE SET last_call_at = NOW()
    RETURNING requests, tokens INTO v_req, v_tok;

    IF v_req >= v_max_req THEN
        UPDATE ers_ai_usage_daily u SET blocked = u.blocked + 1
         WHERE u.user_id = p_user_id AND u.usage_date = v_today;
        RETURN QUERY SELECT FALSE, v_req, v_tok, v_max_req, v_max_tok,
            format('daily AI request limit reached (%s requests)', v_max_req);
        RETURN;
    END IF;

    IF v_tok >= v_max_tok THEN
        UPDATE ers_ai_usage_daily u SET blocked = u.blocked + 1
         WHERE u.user_id = p_user_id AND u.usage_date = v_today;
        RETURN QUERY SELECT FALSE, v_req, v_tok, v_max_req, v_max_tok,
            format('daily AI token budget reached (%s tokens)', v_max_tok);
        RETURN;
    END IF;

    UPDATE ers_ai_usage_daily u
       SET requests = u.requests + 1, last_call_at = NOW()
     WHERE u.user_id = p_user_id AND u.usage_date = v_today
     RETURNING u.requests, u.tokens INTO v_req, v_tok;

    RETURN QUERY SELECT TRUE, v_req, v_tok, v_max_req, v_max_tok, NULL::TEXT;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_ai_budget_status()
 RETURNS TABLE(requests_today integer, tokens_today bigint, max_requests integer, max_tokens bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_uid     UUID := auth.uid();
    v_max_req INTEGER;
    v_max_tok BIGINT;
BEGIN
    IF v_uid IS NULL THEN RETURN; END IF;

    SELECT p.max_requests_per_day, p.max_tokens_per_day
      INTO v_max_req, v_max_tok
      FROM ers_ai_budget_policy p
     WHERE p.id IN (v_uid::TEXT, 'default')
     ORDER BY (p.id = 'default')
     LIMIT 1;

    RETURN QUERY
    SELECT COALESCE(u.requests, 0),
           COALESCE(u.tokens, 0::BIGINT),
           v_max_req,
           v_max_tok
      FROM (SELECT 1) _
      LEFT JOIN ers_ai_usage_daily u
             ON u.user_id = v_uid AND u.usage_date = (NOW() AT TIME ZONE 'UTC')::DATE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_goods_receipt_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF NEW.grn_number IS NULL OR btrim(NEW.grn_number) = '' THEN
        NEW.grn_number := COALESCE(
            public.ers_next_document_number(NEW.company_id, 'GOODS_RECEIPT', 'GRN-', 6),
            -- No tenant yet: the pre-0265 global sequence, so an insert
            -- during the tenancy transition still gets a number.
            'GRN-' || to_char(CURRENT_DATE, 'YYYY') || '-'
                   || lpad(nextval('public.goods_receipt_seq')::TEXT, 6, '0')
        );
    END IF;
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_map_external_ids(p_entity_type text, p_system text, p_pairs jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_caller UUID;
    v_n      INT := 0;
BEGIN
    IF p_pairs IS NULL OR jsonb_typeof(p_pairs) <> 'array' OR jsonb_array_length(p_pairs) = 0 THEN
        RETURN 0;
    END IF;
    IF COALESCE(btrim(p_system), '') = '' THEN
        RAISE EXCEPTION 'ers_map_external_ids: a system name is required';
    END IF;

    BEGIN v_caller := public.caller_company(); EXCEPTION WHEN OTHERS THEN v_caller := NULL; END;

    -- One branch per entity type rather than dynamic SQL: the set of
    -- mappable objects is small, fixed and worth reading.
    IF p_entity_type = 'asset' THEN
        WITH input AS (
            SELECT x.entity_id, btrim(x.external_key) AS external_key
            FROM jsonb_to_recordset(p_pairs) AS x(entity_id UUID, external_key TEXT)
            WHERE COALESCE(btrim(x.external_key), '') <> ''
        ),
        resolved AS (
            SELECT a.company_id, i.entity_id, i.external_key
            FROM input i
            JOIN public.assets a ON a.id = i.entity_id
            -- Someone else's record is skipped, not mapped and not an error.
            WHERE (v_caller IS NULL OR a.company_id = v_caller)
        )
        INSERT INTO public.erp_object_map
            (company_id, system, entity_type, entity_id, external_key, ownership)
        SELECT r.company_id, p_system, 'asset', r.entity_id, r.external_key, 'EXTERNAL'
        FROM resolved r
        -- The key is already claimed by a different record here: a real
        -- ambiguity in their export, left visible rather than re-pointed.
        WHERE NOT EXISTS (
            SELECT 1 FROM public.erp_object_map m
             WHERE m.company_id IS NOT DISTINCT FROM r.company_id
               AND m.system = p_system AND m.entity_type = 'asset'
               AND m.external_key = r.external_key
               AND m.entity_id <> r.entity_id)
        ON CONFLICT (company_id, system, entity_type, entity_id) DO UPDATE
            SET external_key = EXCLUDED.external_key,
                updated_at   = NOW();
        GET DIAGNOSTICS v_n = ROW_COUNT;

    ELSIF p_entity_type = 'inventory_item' THEN
        WITH input AS (
            SELECT x.entity_id, btrim(x.external_key) AS external_key
            FROM jsonb_to_recordset(p_pairs) AS x(entity_id UUID, external_key TEXT)
            WHERE COALESCE(btrim(x.external_key), '') <> ''
        ),
        resolved AS (
            SELECT i2.company_id, i.entity_id, i.external_key
            FROM input i
            JOIN public.inventory_items i2 ON i2.id = i.entity_id
            WHERE (v_caller IS NULL OR i2.company_id = v_caller)
        )
        INSERT INTO public.erp_object_map
            (company_id, system, entity_type, entity_id, external_key, ownership)
        SELECT r.company_id, p_system, 'inventory_item', r.entity_id, r.external_key, 'EXTERNAL'
        FROM resolved r
        WHERE NOT EXISTS (
            SELECT 1 FROM public.erp_object_map m
             WHERE m.company_id IS NOT DISTINCT FROM r.company_id
               AND m.system = p_system AND m.entity_type = 'inventory_item'
               AND m.external_key = r.external_key
               AND m.entity_id <> r.entity_id)
        ON CONFLICT (company_id, system, entity_type, entity_id) DO UPDATE
            SET external_key = EXCLUDED.external_key,
                updated_at   = NOW();
        GET DIAGNOSTICS v_n = ROW_COUNT;

    ELSIF p_entity_type = 'vendor' THEN
        WITH input AS (
            SELECT x.entity_id, btrim(x.external_key) AS external_key
            FROM jsonb_to_recordset(p_pairs) AS x(entity_id UUID, external_key TEXT)
            WHERE COALESCE(btrim(x.external_key), '') <> ''
        ),
        resolved AS (
            SELECT v.company_id, i.entity_id, i.external_key
            FROM input i
            JOIN public.vendors v ON v.id = i.entity_id
            WHERE (v_caller IS NULL OR v.company_id = v_caller)
        )
        INSERT INTO public.erp_object_map
            (company_id, system, entity_type, entity_id, external_key, ownership)
        SELECT r.company_id, p_system, 'vendor', r.entity_id, r.external_key, 'EXTERNAL'
        FROM resolved r
        WHERE NOT EXISTS (
            SELECT 1 FROM public.erp_object_map m
             WHERE m.company_id IS NOT DISTINCT FROM r.company_id
               AND m.system = p_system AND m.entity_type = 'vendor'
               AND m.external_key = r.external_key
               AND m.entity_id <> r.entity_id)
        ON CONFLICT (company_id, system, entity_type, entity_id) DO UPDATE
            SET external_key = EXCLUDED.external_key,
                updated_at   = NOW();
        GET DIAGNOSTICS v_n = ROW_COUNT;

    ELSE
        RAISE EXCEPTION 'ers_map_external_ids: % is not a mappable entity type here', p_entity_type;
    END IF;

    RETURN v_n;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_match_invoice(p_invoice_id uuid)
 RETURNS TABLE(match_status text, payment_block text, variance_amount numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_tol      public.invoice_tolerances%ROWTYPE;
    v_status   TEXT;
    v_block    TEXT;
    v_variance NUMERIC;
    v_po       NUMERIC;
    v_grn      NUMERIC;
    v_user     UUID;
    v_company  UUID;
    v_caller   UUID;
BEGIN
    SELECT m.company_id INTO v_company FROM public.invoice_matches m WHERE m.id = p_invoice_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ers_match_invoice: invoice % not found', p_invoice_id;
    END IF;

    BEGIN v_caller := public.caller_company(); EXCEPTION WHEN OTHERS THEN v_caller := NULL; END;
    IF v_caller IS NOT NULL AND v_company IS NOT NULL AND v_caller <> v_company THEN
        RAISE EXCEPTION 'ers_match_invoice: invoice % belongs to another tenant', p_invoice_id
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- The tenant's own tolerance, then a global row, then the built-in.
    SELECT * INTO v_tol
    FROM public.invoice_tolerances t
    WHERE t.name = 'DEFAULT' AND t.active
      AND (t.company_id = v_company OR t.company_id IS NULL)
    ORDER BY t.company_id NULLS LAST
    LIMIT 1;

    IF NOT FOUND THEN
        -- Never block AP on missing configuration; block on the conservative
        -- side instead. Zero quantity tolerance means an over-billed invoice
        -- is still caught by an unconfigured tenant.
        v_tol.price_abs := 1.00;
        v_tol.price_pct := 2.00;
        v_tol.qty_abs   := 0;
        v_tol.qty_pct   := 0;
    END IF;

    BEGIN v_user := auth.uid(); EXCEPTION WHEN OTHERS THEN v_user := NULL; END;

    WITH gr AS (
        SELECT g.po_line_id, SUM(g.quantity) AS qty
        FROM public.goods_receipts g
        WHERE g.po_line_id IS NOT NULL
        GROUP BY g.po_line_id
    ),
    scored AS (
        SELECT iml.id,
               iml.unit_price,
               pol.unit_cost                                             AS po_unit_cost,
               COALESCE(gr.qty, 0)                                       AS gr_qty,
               ROUND((iml.unit_price - COALESCE(pol.unit_cost, iml.unit_price)) * iml.quantity, 2) AS price_var,
               GREATEST(iml.quantity - COALESCE(gr.qty, 0), 0)           AS qty_over
        FROM public.invoice_match_lines iml
        LEFT JOIN public.purchase_order_lines pol ON pol.id = iml.po_line_id
        LEFT JOIN gr ON gr.po_line_id = iml.po_line_id
        WHERE iml.invoice_id = p_invoice_id
    ),
    verdict AS (
        SELECT s.*,
               (ABS(s.price_var) > v_tol.price_abs
                AND ABS(s.price_var) > (v_tol.price_pct / 100.0)
                    * NULLIF(ABS(s.po_unit_cost * NULLIF(s.gr_qty, 0)), 0)) AS price_bad,
               (s.qty_over > v_tol.qty_abs)                                 AS qty_bad
        FROM scored s
    )
    UPDATE public.invoice_match_lines iml
       SET po_unit_cost   = v.po_unit_cost,
           gr_quantity    = v.gr_qty,
           price_variance = v.price_var,
           qty_variance   = v.qty_over,
           block_reason   = CASE WHEN COALESCE(v.qty_bad, FALSE)   THEN 'QUANTITY'
                                 WHEN COALESCE(v.price_bad, FALSE) THEN 'PRICE' END,
           line_status    = CASE WHEN COALESCE(v.qty_bad, FALSE) OR COALESCE(v.price_bad, FALSE)
                                 THEN 'BLOCKED' ELSE 'MATCHED' END
      FROM verdict v
     WHERE v.id = iml.id;

    SELECT CASE WHEN COUNT(*) FILTER (WHERE l.line_status = 'BLOCKED') > 0 THEN 'BLOCKED'
                WHEN COUNT(*) = 0                                          THEN 'PENDING'
                ELSE 'MATCHED' END,
           MAX(l.block_reason),
           COALESCE(SUM(ABS(l.price_variance)
                        + COALESCE(l.qty_variance, 0) * COALESCE(l.unit_price, 0)), 0)
      INTO v_status, v_block, v_variance
      FROM public.invoice_match_lines l
     WHERE l.invoice_id = p_invoice_id;

    SELECT COALESCE(SUM(pol.qty_ordered * pol.unit_cost), 0),
           COALESCE(SUM(l.gr_quantity  * pol.unit_cost), 0)
      INTO v_po, v_grn
      FROM public.invoice_match_lines l
      LEFT JOIN public.purchase_order_lines pol ON pol.id = l.po_line_id
     WHERE l.invoice_id = p_invoice_id;

    UPDATE public.invoice_matches m
       SET match_status      = v_status,
           payment_block     = v_block,
           po_amount         = v_po,
           grn_amount        = v_grn,
           variance_amount   = ROUND(v_variance, 2),
           tolerance_exceeded = (v_status = 'BLOCKED'),
           matched_by        = COALESCE(m.matched_by, v_user),
           matched_at        = NOW(),
           updated_at        = NOW()
     WHERE m.id = p_invoice_id;

    UPDATE public.purchase_order_lines pol
       SET invoice_matched = (v_status = 'MATCHED'),
           invoice_number  = m.invoice_number,
           updated_at      = NOW()
      FROM public.invoice_match_lines l
      JOIN public.invoice_matches m ON m.id = l.invoice_id
     WHERE l.po_line_id = pol.id AND l.invoice_id = p_invoice_id;

    RETURN QUERY SELECT v_status, v_block, ROUND(v_variance, 2);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_movement_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_mt   public.movement_types%ROWTYPE;
    v_sign SMALLINT;
BEGIN
    IF NEW.movement_type IS NULL THEN
        NEW.movement_type := CASE
            WHEN NEW.transaction_type = 'ISSUE'   AND NEW.wo_id IS NOT NULL THEN '261'
            WHEN NEW.transaction_type = 'ISSUE'                             THEN '201'
            WHEN NEW.transaction_type = 'RECEIPT' AND NEW.po_id IS NOT NULL THEN '101'
            WHEN NEW.transaction_type = 'RECEIPT'                           THEN '501'
            WHEN NEW.transaction_type = 'RETURN'  AND NEW.wo_id IS NOT NULL THEN '262'
            WHEN NEW.transaction_type = 'RETURN'                            THEN '202'
            ELSE '701'
        END;
    END IF;

    SELECT * INTO v_mt FROM public.movement_types WHERE code = NEW.movement_type;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'unknown movement type %', NEW.movement_type;
    END IF;

    v_sign := CASE v_mt.direction WHEN 'OUT' THEN 1 WHEN 'IN' THEN -1 ELSE 0 END;

    IF NEW.total_value IS NULL THEN
        NEW.total_value := ROUND(ABS(COALESCE(NEW.quantity, 0)) * COALESCE(NEW.cost_at_time, 0) * v_sign, 2);
    END IF;

    IF NEW.cost_center_id IS NULL THEN
        IF NEW.wo_id IS NOT NULL THEN
            SELECT r.cost_center_id INTO NEW.cost_center_id
            FROM public.sem_wo_receiver r WHERE r.work_order_id = NEW.wo_id;
        END IF;
        IF NEW.cost_center_id IS NULL THEN
            SELECT i.cost_center_id INTO NEW.cost_center_id
            FROM public.inventory_items i WHERE i.id = NEW.item_id;
        END IF;
    END IF;

    IF NEW.asset_id IS NULL AND NEW.wo_id IS NOT NULL THEN
        SELECT w.asset_id INTO NEW.asset_id FROM public.work_orders w WHERE w.id = NEW.wo_id;
    END IF;

    -- The tenant, by the 0261 rule: from the work order, else the item —
    -- never from the session. The column DEFAULT has already run by the
    -- time a BEFORE trigger fires, so NULL here means "no JWT": a trusted
    -- context whose insert would otherwise die on 0276's NOT NULL.
    IF NEW.company_id IS NULL AND NEW.wo_id IS NOT NULL THEN
        SELECT w.company_id INTO NEW.company_id FROM public.work_orders w WHERE w.id = NEW.wo_id;
    END IF;
    IF NEW.company_id IS NULL AND NEW.item_id IS NOT NULL THEN
        SELECT i.company_id INTO NEW.company_id FROM public.inventory_items i WHERE i.id = NEW.item_id;
    END IF;

    IF NEW.gl_account IS NULL THEN
        SELECT o.gl_account INTO NEW.gl_account
        FROM public.movement_type_gl_overrides o
        WHERE o.code = NEW.movement_type
          AND o.company_id IS NOT DISTINCT FROM NEW.company_id;
        NEW.gl_account := COALESCE(NEW.gl_account, v_mt.gl_account);
    END IF;

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_movement_post_fi()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_posting TEXT;
    v_alloc   UUID;
    v_company UUID;
BEGIN
    SELECT fi_posting INTO v_posting FROM public.movement_types WHERE code = NEW.movement_type;

    IF v_posting <> 'DIRECT' OR COALESCE(NEW.total_value, 0) = 0 THEN
        RETURN NEW;
    END IF;

    -- The movement's own tenant, else the order's, else the item's.
    v_company := NEW.company_id;
    IF v_company IS NULL AND NEW.wo_id IS NOT NULL THEN
        SELECT w.company_id INTO v_company FROM public.work_orders w WHERE w.id = NEW.wo_id;
    END IF;
    IF v_company IS NULL AND NEW.item_id IS NOT NULL THEN
        SELECT i.company_id INTO v_company FROM public.inventory_items i WHERE i.id = NEW.item_id;
    END IF;

    INSERT INTO public.cost_allocations
        (work_order_id, asset_id, cost_center_id, cost_type, amount, quantity, unit,
         posting_date, source, created_by, company_id)
    VALUES
        (NEW.wo_id, NEW.asset_id, NEW.cost_center_id, 'MATERIAL', NEW.total_value,
         ABS(COALESCE(NEW.quantity, 0)), NULL, COALESCE(NEW."timestamp"::DATE, CURRENT_DATE),
         'STOCK_MOVEMENT', NEW.performed_by, v_company)
    RETURNING id INTO v_alloc;

    UPDATE public.inventory_transactions SET cost_allocation_id = v_alloc WHERE id = NEW.id;

    IF NEW.cost_center_id IS NOT NULL THEN
        PERFORM public.ers_refresh_budget_actual(NEW.cost_center_id);
    END IF;

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_next_document_number(p_company uuid, p_object_class text, p_prefix text DEFAULT ''::text, p_pad integer DEFAULT 6)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_allocated BIGINT;
    v_prefix    TEXT;
    v_pad       INT;
BEGIN
    -- No tenant, no range. The caller decides what to do about that.
    IF p_company IS NULL THEN RETURN NULL; END IF;

    -- next_number means "the next one to hand out", so the row starts at 2
    -- having just handed out 1, and RETURNING next_number - 1 is the number
    -- allocated on both the insert and the conflict path. One statement, so
    -- two concurrent receipts cannot take the same number.
    INSERT INTO public.numbering_config_overrides
        (company_id, object_class, prefix, pad, next_number)
    VALUES (p_company, p_object_class, COALESCE(p_prefix, ''), COALESCE(p_pad, 6), 2)
    ON CONFLICT (company_id, object_class) DO UPDATE
        SET next_number = public.numbering_config_overrides.next_number + 1,
            updated_at  = NOW()
    RETURNING next_number - 1, prefix, pad
    INTO v_allocated, v_prefix, v_pad;

    RETURN v_prefix
        || to_char(CURRENT_DATE, 'YYYY') || '-'
        || lpad(v_allocated::TEXT, GREATEST(COALESCE(v_pad, 6), 1), '0');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_prune_reading_points(keep_days integer DEFAULT 90)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    removed BIGINT;
BEGIN
    DELETE FROM ers_sensor_reading_points
     WHERE ts < NOW() - (keep_days || ' days')::INTERVAL;
    GET DIAGNOSTICS removed = ROW_COUNT;
    RETURN removed;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_rca_nodes_stamp_method()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.method IS NULL THEN
        SELECT i.method INTO NEW.method
          FROM ers_rca_investigations i
         WHERE i.id = NEW.investigation_id;
    END IF;
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_refresh_budget_actual(p_cost_center_id uuid, p_fiscal_year integer DEFAULT NULL::integer)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_year    INT := COALESCE(p_fiscal_year, EXTRACT(YEAR FROM CURRENT_DATE)::INT);
    v_total   NUMERIC;
    v_company UUID;
    v_caller  UUID;
BEGIN
    IF p_cost_center_id IS NULL THEN RETURN NULL; END IF;

    SELECT cc.company_id INTO v_company FROM public.cost_centers cc WHERE cc.id = p_cost_center_id;
    BEGIN v_caller := public.caller_company(); EXCEPTION WHEN OTHERS THEN v_caller := NULL; END;
    IF v_caller IS NOT NULL AND v_company IS NOT NULL AND v_caller <> v_company THEN
        RAISE EXCEPTION 'ers_refresh_budget_actual: cost centre belongs to another tenant'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT COALESCE(SUM(c.amount), 0) INTO v_total
    FROM public.cost_allocations c
    WHERE c.cost_center_id = p_cost_center_id
      AND EXTRACT(YEAR FROM COALESCE(c.posting_date, c.created_at::DATE))::INT = v_year;

    UPDATE public.budgets
       SET actual = v_total, updated_at = NOW()
     WHERE cost_center_id = p_cost_center_id
       AND fiscal_year    = v_year;

    RETURN v_total;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_settle_work_order(p_wo_id uuid)
 RETURNS TABLE(cost_type text, cost_center_id uuid, delta_amount numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_asset   UUID;
    v_user    UUID;
    v_company UUID;
    v_caller  UUID;
    v_ids     UUID[];
BEGIN
    -- Serialise per order. delta = actual − posted is only exactly-once if
    -- no other transaction can read `posted` between our read and our
    -- insert; two concurrent settles otherwise both see posted=0 and both
    -- post the full amount. Advisory + xact-scoped: released on commit or
    -- rollback, no table lock held, different orders never wait on each
    -- other.
    PERFORM pg_advisory_xact_lock(hashtextextended(p_wo_id::TEXT, 42));

    SELECT w.asset_id, w.company_id INTO v_asset, v_company
    FROM public.work_orders w WHERE w.id = p_wo_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ers_settle_work_order: work order % not found', p_wo_id;
    END IF;

    BEGIN v_user   := auth.uid();               EXCEPTION WHEN OTHERS THEN v_user := NULL; END;
    BEGIN v_caller := public.caller_company();   EXCEPTION WHEN OTHERS THEN v_caller := NULL; END;

    IF v_caller IS NOT NULL AND v_company IS NOT NULL AND v_caller <> v_company THEN
        RAISE EXCEPTION 'ers_settle_work_order: work order % belongs to another tenant', p_wo_id
            USING ERRCODE = 'insufficient_privilege';
    END IF;
    v_company := COALESCE(v_company, v_caller);

    WITH actual AS (
        SELECT a.cost_type, a.cost_center_id, a.amount, a.quantity, a.unit
        FROM public.sem_wo_actual_lines a
        WHERE a.work_order_id = p_wo_id
    ),
    posted AS (
        SELECT c.cost_type::TEXT            AS cost_type,
               c.cost_center_id             AS cost_center_id,
               SUM(c.amount)                AS amount,
               SUM(COALESCE(c.quantity, 0)) AS quantity
        FROM public.cost_allocations c
        WHERE c.work_order_id = p_wo_id
          AND c.source        = 'WO_SETTLEMENT'
        GROUP BY c.cost_type, c.cost_center_id
    ),
    delta AS (
        SELECT COALESCE(a.cost_type,      p.cost_type)      AS cost_type,
               COALESCE(a.cost_center_id, p.cost_center_id) AS cost_center_id,
               ROUND(COALESCE(a.amount, 0)   - COALESCE(p.amount, 0),   2) AS d_amount,
               ROUND(COALESCE(a.quantity, 0) - COALESCE(p.quantity, 0), 3) AS d_quantity,
               a.unit                                       AS unit
        FROM actual a
        FULL OUTER JOIN posted p
          ON  p.cost_type      = a.cost_type
          AND p.cost_center_id IS NOT DISTINCT FROM a.cost_center_id
    ),
    ins AS (
        INSERT INTO public.cost_allocations
            (work_order_id, asset_id, cost_center_id, cost_type,
             amount, quantity, unit, posting_date, source, created_by, company_id)
        SELECT p_wo_id, v_asset, d.cost_center_id, d.cost_type,
               d.d_amount, NULLIF(d.d_quantity, 0), d.unit,
               CURRENT_DATE, 'WO_SETTLEMENT', v_user, v_company
        FROM delta d
        WHERE ABS(d.d_amount) >= 0.01
        RETURNING public.cost_allocations.id
    )
    SELECT COALESCE(array_agg(ins.id), '{}') INTO v_ids FROM ins;

    PERFORM public.ers_refresh_budget_actual(cc.cost_center_id)
    FROM (
        SELECT DISTINCT c.cost_center_id
        FROM public.cost_allocations c
        WHERE c.work_order_id  = p_wo_id
          AND c.source         = 'WO_SETTLEMENT'
          AND c.cost_center_id IS NOT NULL
    ) cc;

    RETURN QUERY
    SELECT c.cost_type::TEXT, c.cost_center_id, c.amount
    FROM public.cost_allocations c
    WHERE c.id = ANY(v_ids);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_settlement_preview(p_limit integer DEFAULT 500)
 RETURNS TABLE(work_order_id uuid, wo_number text, actual_cost numeric, settled_cost numeric, would_post numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
    SELECT s.work_order_id, s.wo_number, s.actual_cost, s.settled_cost, s.unsettled_variance
    FROM public.sem_wo_settlement s
    WHERE s.wo_state = 'done'
      AND ABS(s.unsettled_variance) >= 0.01
    ORDER BY ABS(s.unsettled_variance) DESC
    LIMIT GREATEST(p_limit, 0);
$function$
;

CREATE OR REPLACE FUNCTION public.ers_settlement_run(p_limit integer DEFAULT 500)
 RETURNS TABLE(work_order_id uuid, wo_number text, postings bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    r        RECORD;
    v_rows   BIGINT;
    v_caller UUID;
BEGIN
    BEGIN v_caller := public.caller_company(); EXCEPTION WHEN OTHERS THEN v_caller := NULL; END;

    FOR r IN
        SELECT s.work_order_id AS id, s.wo_number AS num
        FROM public.sem_wo_settlement s
        JOIN public.work_orders w ON w.id = s.work_order_id
        WHERE s.wo_state = 'done'
          AND ABS(s.unsettled_variance) >= 0.01
          -- sem_wo_settlement is security_invoker, but inside a DEFINER
          -- function the invoker IS the owner, so RLS does not filter here.
          -- The predicate has to be explicit.
          AND (v_caller IS NULL OR w.company_id = v_caller)
        ORDER BY s.wo_number
        LIMIT GREATEST(p_limit, 0)
    LOOP
        SELECT COUNT(*) INTO v_rows FROM public.ers_settle_work_order(r.id);
        work_order_id := r.id;
        wo_number     := r.num;
        postings      := v_rows;
        RETURN NEXT;
    END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ers_wo_state(p_status text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
    WITH s AS (SELECT upper(regexp_replace(btrim(coalesce(p_status, '')), '[\s-]+', '_', 'g')) AS code)
    SELECT CASE
        WHEN (SELECT code FROM s) = '' THEN 'unknown'
        WHEN (SELECT code FROM s) IN (
            'CLOSED','CLSD','CLOSE','TECO','COMP','COMPLETE','COMPLETED','FINISHED',
            'DONE','SETTLED','HISTORICAL'
        ) THEN 'done'
        WHEN (SELECT code FROM s) IN (
            'CANCELLED','CANCELED','CANC','CAN','CNCL','VOID','VOIDED','REJECTED',
            'DELETED','DUPLICATE'
        ) THEN 'void'
        WHEN (SELECT code FROM s) IN (
            'OPEN','WIP','PLAN','PLANNED','PLANNING','REL','RELEASED','CRTD','CREATED',
            'NEW','SCHED','SCHEDULED','INPRG','IN_PROGRESS','INPROGRESS','STARTED',
            'ACTIVE','HOLD','ON_HOLD','WAITING','WAPPR','APPR','APPROVED','ASSIGNED',
            'DISPATCHED','PENDING'
        ) THEN 'open'
        ELSE 'unknown'
    END;
$function$
;

CREATE OR REPLACE FUNCTION public.execute_readonly_sql(query_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET statement_timeout TO '10s'
AS $function$
DECLARE
    result JSONB;
BEGIN
    IF NOT (UPPER(TRIM(query_text)) LIKE 'SELECT%') THEN
        RAISE EXCEPTION 'Only SELECT queries are allowed';
    END IF;

    IF query_text ~* '\b(INSERT|UPDATE|DELETE|DROP|ALTER|TRUNCATE|CREATE|GRANT|REVOKE|EXEC|EXECUTE)\b' THEN
        RAISE EXCEPTION 'Query contains forbidden SQL keywords';
    END IF;

    SET LOCAL transaction_read_only = ON;
    EXECUTE 'SELECT jsonb_agg(row_to_json(t)) FROM (' || query_text || ') t' INTO result;

    RETURN COALESCE(result, '[]'::jsonb);
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'SQL execution error: %', SQLERRM;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.freeze_costs_on_close()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
    -- If status is changing to CLOSED or TECO and wasn't before
    IF (NEW.status IN ('CLOSED', 'TECO') AND OLD.status NOT IN ('CLOSED', 'TECO')) THEN
        NEW.cost_frozen := TRUE;
        -- In a real app, we would sum up labor/materials from sub-tables here.
        -- Usage: NEW.frozen_labor_cost := (SELECT sum(...) FROM ... WHERE wo_id = NEW.id)
        -- For now, we assume these values might be calculated or passed in, or we just lock the current state.
        
        -- Defaulting snapshots if NULL to ensure they are fixed at 0 if no cost exists
        IF NEW.frozen_labor_cost IS NULL THEN NEW.frozen_labor_cost := 0; END IF;
        IF NEW.frozen_material_cost IS NULL THEN NEW.frozen_material_cost := 0; END IF;
        
        NEW.closed_at := NOW();
    END IF;

    -- Prevent Un-Freezing or Modification of Frozen Costs
    IF (OLD.cost_frozen = TRUE) THEN
        IF (NEW.cost_frozen = FALSE) THEN
             RAISE EXCEPTION 'Governance Rule: Cannot un-freeze a Work Order.';
        END IF;
        
        IF (NEW.frozen_labor_cost != OLD.frozen_labor_cost OR NEW.frozen_material_cost != OLD.frozen_material_cost) THEN
             RAISE EXCEPTION 'Governance Rule: Cannot modify costs after they are frozen.';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_audit_number()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN 'AUD-' || EXTRACT(YEAR FROM NOW())::TEXT || '-' ||
         LPAD(nextval('audit_number_seq')::TEXT, 4, '0');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_equipment_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  cfg numbering_config%ROWTYPE;
  ov_equip numbering_config_overrides%ROWTYPE;
  ov_floc  numbering_config_overrides%ROWTYPE;
  has_equip_ov BOOLEAN := false;
  has_floc_ov  BOOLEAN := false;
  eq_prefix TEXT; eq_pad INT; eq_next BIGINT;
  fl_prefix TEXT; fl_pad INT; fl_next BIGINT;
BEGIN
  -- Client-level default singleton (self-heal — 0167).
  SELECT * INTO cfg FROM numbering_config WHERE id = 1 FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO numbering_config (id) VALUES (1) ON CONFLICT (id) DO NOTHING;
    SELECT * INTO cfg FROM numbering_config WHERE id = 1 FOR UPDATE;
  END IF;

  -- Per-company overrides — ONLY when the asset carries a company (else the
  -- singleton path below is identical to pre-0174 behaviour).
  IF NEW.company_id IS NOT NULL THEN
    SELECT * INTO ov_equip FROM numbering_config_overrides
      WHERE company_id = NEW.company_id AND object_class = 'EQUIPMENT' FOR UPDATE;
    has_equip_ov := FOUND;
    SELECT * INTO ov_floc FROM numbering_config_overrides
      WHERE company_id = NEW.company_id AND object_class = 'FLOC' FOR UPDATE;
    has_floc_ov := FOUND;
  END IF;

  -- Effective EQUIPMENT range (override wins, else singleton).
  IF has_equip_ov THEN
    eq_prefix := ov_equip.prefix; eq_pad := ov_equip.pad; eq_next := ov_equip.next_number;
  ELSE
    eq_prefix := COALESCE(cfg.equip_prefix, 'EQ-'); eq_pad := COALESCE(cfg.equip_pad, 6); eq_next := COALESCE(cfg.equip_next, 1);
  END IF;
  -- Effective FLOC range.
  IF has_floc_ov THEN
    fl_prefix := ov_floc.prefix; fl_pad := ov_floc.pad; fl_next := ov_floc.next_number;
  ELSE
    fl_prefix := COALESCE(cfg.floc_prefix, 'FL-'); fl_pad := COALESCE(cfg.floc_pad, 6); fl_next := COALESCE(cfg.floc_next, 1);
  END IF;

  -- Internal Equipment Number — Equipment-class objects only (F-004).
  IF NEW.equipment_number IS NULL AND NEW.hierarchy_level IN ('EQUIPMENT', 'COMPONENT') THEN
    NEW.equipment_number := eq_prefix || LPAD(eq_next::text, eq_pad, '0');
    IF has_equip_ov THEN
      UPDATE numbering_config_overrides SET next_number = eq_next + 1, updated_at = now()
        WHERE company_id = NEW.company_id AND object_class = 'EQUIPMENT';
    ELSE
      UPDATE numbering_config SET equip_next = eq_next + 1, updated_at = now() WHERE id = 1;
    END IF;
  END IF;

  -- Blank Tag ID → auto-number from the correct range (if enabled).
  IF (NEW.tag IS NULL OR btrim(NEW.tag) = '') AND COALESCE(cfg.auto_number_untagged, true) THEN
    IF NEW.hierarchy_level IN ('EQUIPMENT', 'COMPONENT') THEN
      -- Reuse the equipment number just issued (no extra counter advance).
      NEW.tag := COALESCE(NEW.equipment_number, eq_prefix || LPAD(eq_next::text, eq_pad, '0'));
    ELSE
      NEW.tag := fl_prefix || LPAD(fl_next::text, fl_pad, '0');
      IF has_floc_ov THEN
        UPDATE numbering_config_overrides SET next_number = fl_next + 1, updated_at = now()
          WHERE company_id = NEW.company_id AND object_class = 'FLOC';
      ELSE
        UPDATE numbering_config SET floc_next = fl_next + 1, updated_at = now() WHERE id = 1;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_material_number()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Only generate if not explicitly provided (allows manual override)
  IF NEW.material_number IS NULL THEN
    NEW.material_number := 'MAT-' || LPAD(nextval('material_number_seq')::TEXT, 6, '0');
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_permit_number()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    next_seq INT;
BEGIN
    SELECT COALESCE(MAX(
        CAST(SUBSTRING(permit_number FROM 'PTW-\d{4}-(\d+)') AS INT)
    ), 0) + 1
    INTO next_seq
    FROM public.ptw_permits
    WHERE permit_number LIKE 'PTW-' || EXTRACT(YEAR FROM NOW())::TEXT || '-%';

    NEW.permit_number := 'PTW-' || EXTRACT(YEAR FROM NOW())::TEXT || '-' || LPAD(next_seq::TEXT, 3, '0');
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_wo_number()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN 'WO-' || EXTRACT(YEAR FROM NOW())::TEXT || '-' ||
         LPAD(nextval('wo_number_seq')::TEXT, 5, '0');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_asset_mtbf_mttr(p_limit integer DEFAULT 10)
 RETURNS TABLE(asset_id uuid, asset_tag text, asset_name text, wo_count bigint, mtbf_days numeric, mttr_hours numeric, total_downtime numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    a.id                                                AS asset_id,
    a.tag                                               AS asset_tag,
    a.name                                              AS asset_name,
    COUNT(w.id)                                         AS wo_count,
    -- MTBF: total operational period / number of failures
    -- Using date span between first and last WO as operational period
    CASE
      WHEN COUNT(w.id) > 1 THEN
        ROUND(
          EXTRACT(EPOCH FROM (MAX(w.created_at) - MIN(w.created_at))) / 86400.0
          / NULLIF(COUNT(w.id) - 1, 0),
          1
        )
      ELSE 365.0  -- Single failure = assume 1 year MTBF
    END                                                 AS mtbf_days,
    -- MTTR: average downtime per work order
    ROUND(
      COALESCE(AVG(
        CASE WHEN w.actual_downtime_hrs > 0 THEN w.actual_downtime_hrs ELSE NULL END
      ), 0),
      1
    )                                                   AS mttr_hours,
    COALESCE(SUM(w.actual_downtime_hrs), 0)             AS total_downtime
  FROM assets a
  JOIN work_orders w ON w.asset_id = a.id
  WHERE w.status NOT IN ('CANCELLED')
  GROUP BY a.id, a.tag, a.name
  HAVING COUNT(w.id) >= 2  -- Need at least 2 WOs for meaningful MTBF
  ORDER BY COUNT(w.id) DESC
  LIMIT p_limit;
$function$
;

CREATE OR REPLACE FUNCTION public.get_bad_actors(p_limit integer DEFAULT 10)
 RETURNS TABLE(asset_id uuid, asset_tag text, asset_name text, criticality text, wo_count bigint, total_cost numeric, total_downtime_hrs numeric, pct_of_total_wos numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH total AS (
    SELECT COUNT(*)::numeric AS cnt
    FROM work_orders
    WHERE status NOT IN ('CANCELLED')
  )
  SELECT
    a.id                                                       AS asset_id,
    a.tag                                                      AS asset_tag,
    a.name                                                     AS asset_name,
    a.criticality::text                                        AS criticality,
    COUNT(w.id)                                                AS wo_count,
    COALESCE(SUM(
      CASE
        WHEN w.cost_frozen THEN COALESCE(w.frozen_labor_cost, 0) + COALESCE(w.frozen_material_cost, 0)
        ELSE COALESCE(w.total_actual_cost, 0)
      END
    ), 0)                                                      AS total_cost,
    COALESCE(SUM(COALESCE(w.actual_downtime_hrs, 0)), 0)       AS total_downtime_hrs,
    ROUND(COUNT(w.id) * 100.0 / NULLIF(t.cnt, 0), 1)          AS pct_of_total_wos
  FROM assets a
  JOIN work_orders w ON w.asset_id = a.id
  CROSS JOIN total t
  WHERE w.status NOT IN ('CANCELLED')
  GROUP BY a.id, a.tag, a.name, a.criticality, t.cnt
  ORDER BY wo_count DESC, total_cost DESC
  LIMIT p_limit;
$function$
;

CREATE OR REPLACE FUNCTION public.get_downtime_by_failure_mode()
 RETURNS TABLE(failure_mode text, total_hours numeric, wo_count bigint, pct_of_total numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH totals AS (
    SELECT COALESCE(SUM(actual_downtime_hrs), 0) AS grand_total
    FROM work_orders
    WHERE status NOT IN ('CANCELLED')
      AND failure_mode IS NOT NULL
      AND actual_downtime_hrs > 0
  )
  SELECT
    COALESCE(w.failure_mode, 'Unknown')             AS failure_mode,
    ROUND(SUM(w.actual_downtime_hrs), 1)            AS total_hours,
    COUNT(w.id)                                     AS wo_count,
    ROUND(
      SUM(w.actual_downtime_hrs) * 100.0
      / NULLIF(t.grand_total, 0),
      1
    )                                               AS pct_of_total
  FROM work_orders w
  CROSS JOIN totals t
  WHERE w.status NOT IN ('CANCELLED')
    AND w.failure_mode IS NOT NULL
    AND w.actual_downtime_hrs > 0
  GROUP BY w.failure_mode, t.grand_total
  ORDER BY total_hours DESC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_invite(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v public.user_invites;
  v_inviter text;
BEGIN
  SELECT * INTO v FROM public.user_invites WHERE token = p_token;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT u.username INTO v_inviter FROM public.users u WHERE u.id = v.invited_by;

  RETURN jsonb_build_object(
    'found', true,
    -- Effective status: an overdue pending invite reads as expired.
    'status', CASE WHEN v.status = 'pending' AND v.expires_at <= now()
                   THEN 'expired' ELSE v.status END,
    'email', v.email,
    'phone', v.phone,
    'invited_name', v.invited_name,
    'role', v.role,
    'invited_by', coalesce(v_inviter, 'your administrator'),
    'expires_at', v.expires_at
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_oee_losses(p_asset_id uuid DEFAULT NULL::uuid, p_from date DEFAULT (CURRENT_DATE - 30), p_to date DEFAULT CURRENT_DATE)
 RETURNS TABLE(loss_category text, loss_label text, total_minutes numeric, event_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    pde.event_type                                 AS loss_category,
    COALESCE(d.description, pde.event_type)        AS loss_label,
    COALESCE(SUM(pde.duration_min), 0)             AS total_minutes,
    COUNT(*)                                       AS event_count
  FROM production_downtime_events pde
  JOIN production_logs pl ON pl.id = pde.production_log_id
  LEFT JOIN dictionaries d ON d.type = 'OEE_LOSS_CATEGORY' AND d.code = UPPER(pde.event_type)
  WHERE pl.shift_date BETWEEN p_from AND p_to
    AND (p_asset_id IS NULL OR pde.asset_id = p_asset_id)
  GROUP BY pde.event_type, d.description
  ORDER BY total_minutes DESC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_plant_oee(p_from date DEFAULT (CURRENT_DATE - 30), p_to date DEFAULT CURRENT_DATE)
 RETURNS TABLE(availability_pct numeric, performance_pct numeric, quality_pct numeric, oee_pct numeric, total_output numeric, good_output numeric, defect_count numeric, asset_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    ROUND(AVG(c.availability_pct), 1) AS availability_pct,
    ROUND(AVG(c.performance_pct), 1)  AS performance_pct,
    ROUND(AVG(c.quality_pct), 1)      AS quality_pct,
    ROUND(AVG(c.oee_pct), 1)          AS oee_pct,
    SUM(c.total_output)               AS total_output,
    SUM(c.good_output)                AS good_output,
    SUM(c.defect_count)               AS defect_count,
    COUNT(*)                          AS asset_count
  FROM compute_oee(NULL, p_from, p_to) c;
$function$
;

CREATE OR REPLACE FUNCTION public.get_reliability_kpis()
 RETURNS TABLE(total_wos bigint, avg_mttr_hrs numeric, availability_pct numeric, total_cost numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH wo_metrics AS (
    SELECT
      COUNT(*)                                           AS total_wos,
      COALESCE(SUM(
        CASE
          WHEN cost_frozen THEN COALESCE(frozen_labor_cost, 0) + COALESCE(frozen_material_cost, 0)
          ELSE COALESCE(total_actual_cost, 0)
        END
      ), 0)                                              AS total_cost,
      COALESCE(AVG(
        CASE
          WHEN actual_downtime_hrs IS NOT NULL AND actual_downtime_hrs > 0
          THEN actual_downtime_hrs
          ELSE NULL
        END
      ), 0)                                              AS avg_mttr_hrs,
      COALESCE(SUM(COALESCE(actual_downtime_hrs, 0)), 0) AS total_downtime_hrs
    FROM work_orders
    WHERE status NOT IN ('CANCELLED')
  )
  SELECT
    wm.total_wos,
    ROUND(wm.avg_mttr_hrs, 2)                           AS avg_mttr_hrs,
    -- Availability = (total_operational_hrs - downtime) / total_operational_hrs × 100
    -- Using 8760 hrs/year as baseline (365 × 24)
    ROUND(
      GREATEST(0, LEAST(100,
        (8760.0 - wm.total_downtime_hrs) / 8760.0 * 100
      )), 1
    )                                                    AS availability_pct,
    wm.total_cost
  FROM wo_metrics wm;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  linked_contact_id UUID;
  user_role text[];
  contact_username text;
BEGIN
  BEGIN
    SELECT id, roles INTO linked_contact_id, user_role
    FROM public.contacts
    WHERE email = NEW.email
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    linked_contact_id := NULL;
    user_role := NULL;
  END;

  contact_username := split_part(NEW.email, '@', 1);

  INSERT INTO public.users (id, username, email, contact_id, status, roles)
  VALUES (
    NEW.id,
    contact_username,
    NEW.email,
    linked_contact_id,
    'active',
    to_jsonb(COALESCE(user_role, ARRAY['TECHNICIAN']))
  )
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT EXISTS (
        SELECT 1 FROM users u
        WHERE (
                lower(coalesce(u.email, '')) = lower(coalesce(auth.jwt() ->> 'email', ''))
             OR lower(coalesce(u.username, '')) = lower(split_part(coalesce(auth.jwt() ->> 'email', ''), '@', 1))
              )
          AND coalesce(u.status, 'active') = 'active'
          AND u.roles ?| ARRAY['SUPER_ADMIN', 'SYS_ADMIN']
    );
$function$
;

CREATE OR REPLACE FUNCTION public.jsa_templates_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at := timezone('utc'::text, now());
    RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.log_audit_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    user_id UUID;
    actor_email TEXT;
    old_data JSONB;
    new_data JSONB;
    changes_json JSONB;
BEGIN
    -- Identity from the request JWT (both may be NULL for system writes).
    BEGIN
        user_id := auth.uid();
    EXCEPTION WHEN OTHERS THEN
        user_id := NULL;
    END;
    BEGIN
        actor_email := auth.jwt() ->> 'email';
    EXCEPTION WHEN OTHERS THEN
        actor_email := NULL;
    END;

    IF (TG_OP = 'DELETE') THEN
        old_data := to_jsonb(OLD);
        changes_json := jsonb_build_object('old', old_data, 'actor_email', actor_email);
        INSERT INTO audit_logs (table_name, record_id, action, changed_by, changes, company_id)
        VALUES (TG_TABLE_NAME, OLD.id::TEXT, 'DELETE', user_id, changes_json,
                   coalesce(nullif(old_data->>'company_id','')::uuid,
                            CASE WHEN TG_TABLE_NAME = 'companies' THEN nullif(old_data->>'id','')::uuid END,
                            public.caller_company()));
        RETURN OLD;
    ELSIF (TG_OP = 'UPDATE') THEN
        old_data := to_jsonb(OLD);
        new_data := to_jsonb(NEW);
        changes_json := jsonb_build_object('old', old_data, 'new', new_data, 'actor_email', actor_email);
        INSERT INTO audit_logs (table_name, record_id, action, changed_by, changes, company_id)
        VALUES (TG_TABLE_NAME, NEW.id::TEXT, 'UPDATE', user_id, changes_json,
                   coalesce(nullif(new_data->>'company_id','')::uuid,
                            CASE WHEN TG_TABLE_NAME = 'companies' THEN nullif(new_data->>'id','')::uuid END,
                            public.caller_company()));
        RETURN NEW;
    ELSIF (TG_OP = 'INSERT') THEN
        new_data := to_jsonb(NEW);
        changes_json := jsonb_build_object('new', new_data, 'actor_email', actor_email);
        INSERT INTO audit_logs (table_name, record_id, action, changed_by, changes, company_id)
        VALUES (TG_TABLE_NAME, NEW.id::TEXT, 'INSERT', user_id, changes_json,
                   coalesce(nullif(new_data->>'company_id','')::uuid,
                            CASE WHEN TG_TABLE_NAME = 'companies' THEN nullif(new_data->>'id','')::uuid END,
                            public.caller_company()));
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.provision_tenant(p_name text, p_code text, p_seed_ids uuid[], p_currency text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_tier text DEFAULT 'starter'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    v_origin   uuid;
    v_new      uuid := gen_random_uuid();
    v_expected int  := coalesce(array_length(p_seed_ids, 1), 0);
    v_cloned   int  := 0;
    v_n        int;
    t          text;
    cols       text;
    exprs      text;
BEGIN
    IF p_code IS NULL OR btrim(p_code) = '' OR p_name IS NULL OR btrim(p_name) = '' THEN
        RAISE EXCEPTION 'provision_tenant: name and code are required';
    END IF;
    IF p_tier NOT IN ('starter', 'professional', 'enterprise') THEN
        RAISE EXCEPTION 'provision_tenant: unknown tier %', p_tier;
    END IF;
    IF EXISTS (SELECT 1 FROM public.companies WHERE code = p_code) THEN
        RAISE EXCEPTION 'provision_tenant: company code % already exists', p_code;
    END IF;

    SELECT id INTO v_origin FROM public.companies WHERE active IS TRUE ORDER BY created_at ASC LIMIT 1;
    IF v_origin IS NULL THEN
        RAISE EXCEPTION 'provision_tenant: no active origin company to clone seeds from';
    END IF;

    INSERT INTO public.companies (id, code, name, active, edition, currency, country, tier)
    SELECT v_new, p_code, p_name, true, edition, coalesce(p_currency, currency), coalesce(p_country, country), p_tier
      FROM public.companies WHERE id = v_origin;

    CREATE TEMP TABLE _map (old_id uuid PRIMARY KEY, new_id uuid NOT NULL) ON COMMIT DROP;
    INSERT INTO _map
    SELECT id, gen_random_uuid() FROM public.audit_templates          WHERE company_id = v_origin AND id = ANY (p_seed_ids)
    UNION ALL
    SELECT id, gen_random_uuid() FROM public.audit_template_sections  WHERE company_id = v_origin AND id = ANY (p_seed_ids)
    UNION ALL
    SELECT id, gen_random_uuid() FROM public.audit_template_questions WHERE company_id = v_origin AND id = ANY (p_seed_ids)
    UNION ALL
    SELECT id, gen_random_uuid() FROM public.notification_rules       WHERE company_id = v_origin AND id = ANY (p_seed_ids)
    UNION ALL
    SELECT id, gen_random_uuid() FROM public.notification_channels    WHERE company_id = v_origin AND id = ANY (p_seed_ids)
    UNION ALL
    SELECT id, gen_random_uuid() FROM public.message_templates        WHERE company_id = v_origin AND id = ANY (p_seed_ids);

    FOREACH t IN ARRAY ARRAY['audit_templates', 'audit_template_sections',
                             'audit_template_questions', 'notification_rules',
                             'notification_channels', 'message_templates'] LOOP
        SELECT string_agg(quote_ident(column_name), ', ' ORDER BY ordinal_position),
               string_agg(
                   CASE column_name
                       WHEN 'id'                THEN 'm.new_id'
                       WHEN 'company_id'        THEN '$1'
                       WHEN 'created_by'        THEN 'NULL'
                       WHEN 'template_id'       THEN '(SELECT new_id FROM _map WHERE old_id = s.template_id)'
                       WHEN 'section_id'        THEN '(SELECT new_id FROM _map WHERE old_id = s.section_id)'
                       WHEN 'parent_section_id' THEN '(SELECT new_id FROM _map WHERE old_id = s.parent_section_id)'
                       ELSE 's.' || quote_ident(column_name)
                   END, ', ' ORDER BY ordinal_position)
          INTO cols, exprs
          FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = t AND is_generated = 'NEVER';

        EXECUTE format(
            'INSERT INTO public.%I (%s)
             SELECT %s FROM public.%I s JOIN _map m ON m.old_id = s.id
              WHERE s.company_id = $2 AND s.id = ANY ($3)',
            t, cols, exprs, t)
        USING v_new, v_origin, p_seed_ids;

        GET DIAGNOSTICS v_n = ROW_COUNT;
        v_cloned := v_cloned + v_n;
    END LOOP;

    IF v_cloned <> v_expected THEN
        RAISE EXCEPTION 'provision_tenant: % seed id(s) passed but % row(s) cloned — the id list does not match the live seed rows',
            v_expected, v_cloned;
    END IF;

    RETURN v_new;
END $function$
;

CREATE OR REPLACE FUNCTION public.refresh_asset_reliability_stats()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  WITH asset_stats AS (
    SELECT
      w.asset_id,
      COUNT(w.id)                                        AS total_failures,
      CASE
        WHEN COUNT(w.id) > 1 THEN
          ROUND(
            EXTRACT(EPOCH FROM (MAX(w.created_at) - MIN(w.created_at))) / 86400.0
            / NULLIF(COUNT(w.id) - 1, 0),
            1
          )
        WHEN COUNT(w.id) = 1 THEN 365.0
        ELSE NULL
      END                                                AS calc_mtbf_days,
      ROUND(
        COALESCE(AVG(
          CASE WHEN w.actual_downtime_hrs > 0 THEN w.actual_downtime_hrs ELSE NULL END
        ), 0),
        1
      )                                                  AS calc_mttr_hours,
      COALESCE(SUM(w.actual_downtime_hrs), 0)            AS total_downtime_hrs,
      COUNT(w.id) FILTER (
        WHERE EXTRACT(YEAR FROM w.created_at) = EXTRACT(YEAR FROM NOW())
      )                                                  AS calc_failure_count_ytd
    FROM work_orders w
    WHERE w.status NOT IN ('CANCELLED')
    GROUP BY w.asset_id
  )
  UPDATE public.assets a
  SET
    mtbf_days         = s.calc_mtbf_days,
    mttr_hours        = s.calc_mttr_hours,
    failure_count_ytd = s.calc_failure_count_ytd,
    running_hours     = GREATEST(0,
      ROUND(
        EXTRACT(EPOCH FROM (NOW() - a.created_at)) / 3600.0
        - s.total_downtime_hrs,
        0
      )
    )
  FROM asset_stats s
  WHERE a.id = s.asset_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.role_can(p_role text, p_overrides jsonb, p_module text, p_action text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
    SELECT CASE
        -- A per-user override wins outright, in EITHER direction. Tested for
        -- NULL rather than truthiness so that an explicit false WITHDRAWS
        -- permission instead of falling through to the template.
        WHEN p_overrides -> p_module ->> p_action IS NOT NULL
            THEN (p_overrides -> p_module ->> p_action)::boolean
        ELSE EXISTS (
            SELECT 1 FROM public.role_permissions rp
            WHERE rp.role = CASE
                    WHEN p_role IS NOT NULL AND EXISTS (
                        SELECT 1 FROM public.role_permissions k WHERE k.role = p_role
                    ) THEN p_role
                    ELSE '__default__'
                 END
              AND rp.module = p_module
              AND rp.action = p_action
        )
    END;
$function$
;

CREATE OR REPLACE FUNCTION public.rpc_pareto_analysis(p_parent_asset_id uuid DEFAULT NULL::uuid, p_hierarchy_level text DEFAULT 'EQUIPMENT'::text, p_criteria text DEFAULT 'cost'::text, p_date_from timestamp with time zone DEFAULT (now() - '1 year'::interval), p_date_to timestamp with time zone DEFAULT now(), p_wo_types text[] DEFAULT ARRAY['CM'::text, 'PM'::text], p_limit integer DEFAULT 20)
 RETURNS TABLE(asset_id uuid, asset_tag text, asset_name text, hierarchy_level text, criticality text, metric_value numeric, metric_unit text, event_count bigint, pct_of_total numeric, cumulative_pct numeric, rank bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
#variable_conflict use_column
BEGIN
  RETURN QUERY
  WITH RECURSIVE asset_tree AS (
    SELECT a.id, a.tag, a.name, a.hierarchy_level AS hlevel, a.criticality AS crit, a.parent_id,
      CASE WHEN a.hierarchy_level::text = p_hierarchy_level THEN a.id ELSE NULL::UUID END AS rollup_id
    FROM public.assets a
    WHERE CASE WHEN p_parent_asset_id IS NULL THEN a.parent_id IS NULL ELSE a.parent_id = p_parent_asset_id END
    UNION ALL
    SELECT c.id, c.tag, c.name, c.hierarchy_level, c.criticality, c.parent_id,
      CASE WHEN c.hierarchy_level::text = p_hierarchy_level THEN c.id ELSE at.rollup_id END
    FROM public.assets c
    JOIN asset_tree at ON c.parent_id = at.id
  ),
  parent_self AS (
    SELECT a.id, a.tag, a.name, a.hierarchy_level AS hlevel, a.criticality AS crit, a.parent_id,
      CASE WHEN a.hierarchy_level::text = p_hierarchy_level THEN a.id ELSE NULL::UUID END AS rollup_id
    FROM public.assets a
    WHERE p_parent_asset_id IS NOT NULL AND a.id = p_parent_asset_id
  ),
  full_tree AS ( SELECT * FROM asset_tree UNION ALL SELECT * FROM parent_self ),
  scope AS (
    SELECT ft.id AS leaf_id, COALESCE(ft.rollup_id, ft.id) AS target_id
    FROM full_tree ft
    WHERE ft.rollup_id IS NOT NULL OR ft.hlevel::text = p_hierarchy_level
  ),
  wo_filtered AS (
    SELECT wo.id AS wo_id, wo.asset_id, wo.type AS wo_type, wo.est_duration, wo.actual_downtime_hrs
    FROM public.work_orders wo
    WHERE wo.status IN ('CLOSED', 'TECO')
      AND wo.created_at >= p_date_from
      AND wo.created_at <= p_date_to
      AND wo.asset_id IN (SELECT leaf_id FROM scope)
      AND upper(coalesce(wo.type, '')) !~ '(PREVENT|PREDICT|INSPECT|SCHEDUL|\mPM\M|\mPDM\M)'
      AND (
            upper(coalesce(wo.type, '')) ~ '(CORRECT|BREAK|EMERG|REPAIR|\mCM\M)'
            OR EXISTS (SELECT 1 FROM public.wo_failure_data fd
                       WHERE fd.wo_id = wo.id AND fd.failure_mode_code IS NOT NULL)
          )
  ),
  wo_costs AS (
    SELECT wf.wo_id, wf.asset_id,
      COALESCE(lab.labor_total, 0) + COALESCE(prt.parts_total, 0) AS total_cost
    FROM wo_filtered wf
    LEFT JOIN LATERAL ( SELECT SUM(wl.hours_worked * wl.rate_per_hour) AS labor_total
      FROM public.work_order_labor wl WHERE wl.wo_id = wf.wo_id ) lab ON true
    LEFT JOIN LATERAL ( SELECT SUM(wp.quantity * wp.unit_cost) AS parts_total
      FROM public.work_order_parts wp WHERE wp.wo_id = wf.wo_id ) prt ON true
  ),
  agg AS (
    SELECT s.target_id,
      CASE p_criteria
        WHEN 'cost'         THEN COALESCE(SUM(wc.total_cost), 0)
        WHEN 'downtime'     THEN COALESCE(SUM(COALESCE(wf.actual_downtime_hrs, wf.est_duration, 0)), 0)
        WHEN 'wo_frequency' THEN COUNT(wf.wo_id)::NUMERIC
        ELSE 0
      END AS metric_val,
      COUNT(wf.wo_id) AS evt_count
    FROM scope s
    LEFT JOIN wo_filtered wf ON wf.asset_id = s.leaf_id
    LEFT JOIN wo_costs wc ON wc.wo_id = wf.wo_id
    GROUP BY s.target_id
  ),
  ranked AS (
    SELECT a2.id AS asset_id, a2.tag AS asset_tag, a2.name AS asset_name,
      a2.hierarchy_level::TEXT AS hierarchy_level, a2.criticality::TEXT AS criticality,
      COALESCE(agg.metric_val, 0) AS metric_value,
      CASE p_criteria WHEN 'cost' THEN '$' WHEN 'downtime' THEN 'hrs' WHEN 'wo_frequency' THEN 'WOs' ELSE '' END AS metric_unit,
      COALESCE(agg.evt_count, 0) AS event_count,
      ROW_NUMBER() OVER (ORDER BY COALESCE(agg.metric_val, 0) DESC) AS rank
    FROM agg
    JOIN public.assets a2 ON a2.id = agg.target_id
    WHERE COALESCE(agg.metric_val, 0) > 0
  ),
  grand AS ( SELECT SUM(ranked.metric_value) AS total FROM ranked ),
  final AS (
    SELECT r.asset_id, r.asset_tag, r.asset_name, r.hierarchy_level, r.criticality,
      ROUND(r.metric_value, 2) AS metric_value, r.metric_unit, r.event_count,
      CASE WHEN g.total > 0 THEN ROUND((r.metric_value / g.total) * 100, 1) ELSE 0 END AS pct_of_total,
      CASE WHEN g.total > 0 THEN ROUND((SUM(r.metric_value) OVER (ORDER BY r.rank)) / g.total * 100, 1) ELSE 0 END AS cumulative_pct,
      r.rank
    FROM ranked r CROSS JOIN grand g
    ORDER BY r.rank
    LIMIT p_limit
  )
  SELECT f.asset_id, f.asset_tag, f.asset_name, f.hierarchy_level, f.criticality,
    f.metric_value, f.metric_unit, f.event_count, f.pct_of_total, f.cumulative_pct, f.rank
  FROM final f;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.search_manual_chunks(q text, asset text DEFAULT NULL::text, max_results integer DEFAULT 8)
 RETURNS TABLE(id uuid, source text, chunk_index integer, chunk_text text, page_number integer, asset_tag text, equipment_class text, document_type text, score real)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
    SELECT d.id, d.source, d.chunk_index, d.chunk_text, d.page_number,
           d.asset_tag, d.equipment_class, d.document_type,
           ts_rank_cd(d.fts, websearch_to_tsquery('english', q)) AS score
    FROM ers_rag_documents d
    WHERE d.fts @@ websearch_to_tsquery('english', q)
      AND (asset IS NULL OR d.asset_tag ILIKE asset)
    ORDER BY score DESC, d.source, d.chunk_index
    LIMIT GREATEST(1, LEAST(COALESCE(max_results, 8), 25));
$function$
;

CREATE OR REPLACE FUNCTION public.set_updated_at_col()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_user_login_active(p_user_id uuid, p_active boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$ BEGIN
  UPDATE auth.users
  SET banned_until = CASE WHEN p_active THEN NULL ELSE '2999-12-31 00:00:00+00'::timestamptz END
  WHERE id = p_user_id;
END; $function$
;

CREATE OR REPLACE FUNCTION public.stamp_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    j   jsonb;
    v   uuid;
    ref text;
BEGIN
    -- The common case: the DEFAULT already stamped it (defaults run before
    -- BEFORE-triggers), or the client supplied it. One IF and out.
    IF NEW.company_id IS NOT NULL THEN
        RETURN NEW;
    END IF;

    j := to_jsonb(NEW);

    -- asset-anchored rows (sensor points, readings, alerts, twin states…)
    ref := coalesce(j->>'asset_id', '');
    IF ref <> '' THEN
        SELECT company_id INTO v FROM public.assets WHERE id = ref::uuid;
        IF v IS NOT NULL THEN NEW.company_id := v; RETURN NEW; END IF;
    END IF;

    -- work-order-anchored rows
    ref := coalesce(j->>'wo_id', j->>'work_order_id', '');
    IF ref <> '' THEN
        SELECT company_id INTO v FROM public.work_orders WHERE id::text = ref;
        IF v IS NOT NULL THEN NEW.company_id := v; RETURN NEW; END IF;
    END IF;

    -- user-anchored rows (AI logs, usage counters)
    ref := coalesce(j->>'user_id', j->>'changed_by', '');
    IF ref <> '' THEN
        SELECT company_id INTO v FROM public.users WHERE id::text = ref;
        IF v IS NOT NULL THEN NEW.company_id := v; RETURN NEW; END IF;
    END IF;

    -- recipient-anchored rows (outbox, notifications) — recipient columns are
    -- TEXT and have historically held users.id OR contacts.id, so try both.
    ref := coalesce(j->>'recipient_user_id', j->>'recipient_id', '');
    IF ref <> '' THEN
        SELECT company_id INTO v FROM public.users WHERE id::text = ref;
        IF v IS NULL THEN
            SELECT company_id INTO v FROM public.contacts WHERE id::text = ref;
        END IF;
        IF v IS NOT NULL THEN NEW.company_id := v; RETURN NEW; END IF;
    END IF;

    ref := coalesce(j->>'connector_id', '');
    IF ref <> '' THEN
        SELECT company_id INTO v FROM public.connectors WHERE id::text = ref;
        IF v IS NOT NULL THEN NEW.company_id := v; RETURN NEW; END IF;
    END IF;

    ref := coalesce(j->>'contact_id', '');
    IF ref <> '' THEN
        SELECT company_id INTO v FROM public.contacts WHERE id::text = ref;
        IF v IS NOT NULL THEN NEW.company_id := v; RETURN NEW; END IF;
    END IF;

    -- Nothing derived. Leave it NULL: the NOT NULL constraint makes that a
    -- loud, attributable error at the writer, instead of a row no tenant can
    -- ever see. Silent loss is the failure mode this migration exists to end.
    RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.sync_stock_on_hand()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Update item for NEW record if it exists (INSERT / UPDATE)
    IF NEW.item_id IS NOT NULL THEN
        UPDATE inventory_items
        SET stock_on_hand = (
            SELECT COALESCE(SUM(quantity), 0)
            FROM inventory_stock
            WHERE item_id = NEW.item_id
        )
        WHERE id = NEW.item_id;
    END IF;

    -- Update item for OLD record if it exists and is different (DELETE / UPDATE item_id)
    IF OLD.item_id IS NOT NULL AND (NEW.item_id IS NULL OR NEW.item_id <> OLD.item_id) THEN
        UPDATE inventory_items
        SET stock_on_hand = (
            SELECT COALESCE(SUM(quantity), 0)
            FROM inventory_stock
            WHERE item_id = OLD.item_id
        )
        WHERE id = OLD.item_id;
    END IF;
    
    RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_stock_reserved()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_item_ids UUID[];
BEGIN
    IF TG_TABLE_NAME = 'work_order_parts' THEN
        IF TG_OP = 'INSERT' THEN
            v_item_ids := ARRAY[NEW.item_id];
        ELSIF TG_OP = 'DELETE' THEN
            v_item_ids := ARRAY[OLD.item_id];
        ELSE
            v_item_ids := ARRAY[NEW.item_id, OLD.item_id];
        END IF;
    ELSE
        -- work_orders status change: refresh every item on that order
        SELECT COALESCE(array_agg(DISTINCT item_id), '{}') INTO v_item_ids
        FROM work_order_parts WHERE wo_id = NEW.id;
    END IF;

    UPDATE inventory_items i
       SET stock_reserved = COALESCE((
               SELECT SUM(wop.quantity)
                 FROM work_order_parts wop
                 JOIN work_orders wo ON wo.id = wop.wo_id
                WHERE wop.item_id = i.id
                  -- status is enum wo_status: compare as text (NULL = open,
                  -- matching the client-side derivation)
                  AND (wo.status IS NULL
                       OR wo.status::text NOT IN ('CLOSED', 'CANC', 'CANCELLED', 'TECO'))
           ), 0)
     WHERE i.id = ANY(v_item_ids) AND i.id IS NOT NULL;

    RETURN COALESCE(NEW, OLD);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tenancy_policy_gaps()
 RETURNS TABLE(kind text, object_name text, detail text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
    WITH tenant_tables AS (
        SELECT c.oid, c.relname
          FROM pg_class c
          JOIN pg_namespace n ON n.oid = c.relnamespace
         WHERE n.nspname = 'public'
           AND c.relkind = 'r'
           AND EXISTS (SELECT 1 FROM information_schema.columns col
                        WHERE col.table_schema = 'public'
                          AND col.table_name = c.relname
                          AND col.column_name = 'company_id')
           AND c.relname NOT IN ('users', 'companies')
    )
    SELECT 'rls_disabled'::text, t.relname::text,
           format('rls_enabled=%s policies=%s', c.relrowsecurity,
                  (SELECT count(*) FROM pg_policies p
                    WHERE p.schemaname = 'public' AND p.tablename = t.relname))
      FROM tenant_tables t
      JOIN pg_class c ON c.oid = t.oid
     WHERE c.relrowsecurity = false
        OR NOT EXISTS (SELECT 1 FROM pg_policies p
                        WHERE p.schemaname = 'public' AND p.tablename = t.relname)

    UNION ALL

    SELECT 'policy_ungated'::text,
           format('%s.%s', p.tablename, p.policyname)::text,
           format('cmd=%s', p.cmd)
      FROM pg_policies p
      JOIN tenant_tables t ON t.relname = p.tablename
     WHERE p.schemaname = 'public'
       AND p.permissive = 'PERMISSIVE'
       AND coalesce(p.qual, '') || coalesce(p.with_check, '') NOT LIKE '%caller_company%'

    UNION ALL

    -- The tenant test must BIND: followed by AND, or by nothing.
    SELECT 'tenant_test_not_binding'::text,
           format('%s.%s', p.tablename, p.policyname)::text,
           format('cmd=%s expr=%s', p.cmd, left(e.flat, 90))
      FROM pg_policies p
      JOIN tenant_tables t ON t.relname = p.tablename
      CROSS JOIN LATERAL (
          SELECT coalesce(p.qual, p.with_check, '') AS expr,
                 btrim(regexp_replace(
                     regexp_replace(coalesce(p.qual, p.with_check, ''), '[()]', '', 'g'),
                     '\s+', ' ', 'g')) AS flat
      ) AS e
     WHERE p.schemaname = 'public'
       AND p.permissive = 'PERMISSIVE'
       AND e.expr LIKE '%caller_company%'
       AND e.flat !~ ('^company_id = SELECT caller_company AS caller_company( AND |$)'
                      '|^company_id IS NULL OR company_id = SELECT caller_company AS caller_company( AND |$)')

    UNION ALL

    SELECT 'view_unfiltered'::text, c.relname::text,
           'definer view, no caller_company() filter'::text
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'public'
       AND c.relkind = 'v'
       AND coalesce((SELECT option_value FROM pg_options_to_table(c.reloptions)
                      WHERE option_name = 'security_invoker'), 'false') <> 'true'
       AND pg_get_viewdef(c.oid, true) NOT LIKE '%caller_company%';
$function$
;

CREATE OR REPLACE FUNCTION public.trg_settle_on_done()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF public.ers_wo_state(NEW.status::TEXT) = 'done'
       AND public.ers_wo_state(COALESCE(OLD.status::TEXT, '')) IS DISTINCT FROM 'done'
    THEN
        -- Closing work must never be blocked by the finance ledger. A failed
        -- settlement leaves a visible variance on sem_wo_settlement, which
        -- ers_settlement_run() clears on the next pass.
        BEGIN
            PERFORM * FROM public.ers_settle_work_order(NEW.id);
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'settlement failed for work order % (%): %', NEW.id, NEW.wo_number, SQLERRM;
        END;
    END IF;
    RETURN NEW;
END;
$function$
;

