    frozen_total_cost numeric DEFAULT 0,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    review_notes text,
    est_duration integer DEFAULT 0,
    scope text,
    actual_downtime_hrs numeric,
    failure_mode text,
    failure_code text,
    recurring_work_id text,
    warranty_flag boolean DEFAULT false,
    warranty_id uuid,
    warranty_claim_id uuid,
    work_center_id uuid,
    import_batch_id uuid,
    company_id uuid DEFAULT caller_company() NOT NULL
);

CREATE TABLE IF NOT EXISTS public.writeback_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    target_id uuid,
    proposal_id uuid NOT NULL,
    status text NOT NULL,
    http_status integer,
    request_payload jsonb,
    response_excerpt text,
    error text,
    delivered_at timestamp with time zone DEFAULT now() NOT NULL,
    company_id uuid DEFAULT caller_company() NOT NULL
);

CREATE TABLE IF NOT EXISTS public.writeback_targets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    system text DEFAULT 'generic'::text NOT NULL,
    endpoint_url text NOT NULL,
    method text DEFAULT 'POST'::text NOT NULL,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_active boolean DEFAULT false NOT NULL,
    last_delivery_at timestamp with time zone,
    last_status text,
    last_error text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    company_id uuid DEFAULT caller_company() NOT NULL
);


