-- ══════════════════════════════════════════════
-- Views
-- ══════════════════════════════════════════════

CREATE OR REPLACE VIEW public.contact_directory AS
 SELECT id,
    name
   FROM contacts
  WHERE company_id = (( SELECT caller_company() AS caller_company));

CREATE OR REPLACE VIEW public.dictionaries_effective WITH (security_invoker = true) AS
 SELECT DISTINCT ON (type, code) id,
    type,
    code,
    description,
    is_locked,
    active,
    properties,
    updated_at,
    company_id
   FROM dictionaries
  WHERE company_id IS NULL OR company_id = (( SELECT caller_company() AS caller_company))
  ORDER BY type, code, (company_id IS NULL);

CREATE OR REPLACE VIEW public.hierarchy_config_effective WITH (security_invoker = true) AS
 SELECT id,
    levels,
    updated_at,
    company_id
   FROM hierarchy_config
  WHERE company_id IS NULL OR company_id = (( SELECT caller_company() AS caller_company))
  ORDER BY (company_id IS NULL)
 LIMIT 1;

CREATE OR REPLACE VIEW public.maintenance_forecasts AS
 SELECT id,
    code,
    title,
    asset_id,
    frequency_interval,
    frequency_unit,
    est_labor_cost,
    est_material_cost,
    est_labor_cost + est_material_cost AS cost_per_event,
        CASE
            WHEN frequency_unit = 'Days'::text THEN 365.0 / NULLIF(frequency_interval, 0)::numeric
            WHEN frequency_unit = 'Weeks'::text THEN 52.0 / NULLIF(frequency_interval, 0)::numeric
            WHEN frequency_unit = 'Months'::text THEN 12.0 / NULLIF(frequency_interval, 0)::numeric
            WHEN frequency_unit = 'Years'::text THEN 1.0 / NULLIF(frequency_interval, 0)::numeric
            ELSE 0::numeric
        END AS annual_frequency,
    (est_labor_cost + est_material_cost) *
        CASE
            WHEN frequency_unit = 'Days'::text THEN 365.0 / NULLIF(frequency_interval, 0)::numeric
            WHEN frequency_unit = 'Weeks'::text THEN 52.0 / NULLIF(frequency_interval, 0)::numeric
            WHEN frequency_unit = 'Months'::text THEN 12.0 / NULLIF(frequency_interval, 0)::numeric
            WHEN frequency_unit = 'Years'::text THEN 1.0 / NULLIF(frequency_interval, 0)::numeric
            ELSE 0::numeric
        END AS annual_estimated_spend,
    next_due_date
   FROM recurring_work rw
  WHERE company_id = (( SELECT caller_company() AS caller_company)) AND active = true AND status = 'ACTIVE'::text;

CREATE OR REPLACE VIEW public.manufacturers_effective WITH (security_invoker = true) AS
 SELECT DISTINCT ON (name) id,
    name,
    country,
    website,
    phone,
    email,
    notes,
    active,
    created_at,
    updated_at,
    company_id
   FROM manufacturers
  WHERE company_id IS NULL OR company_id = (( SELECT caller_company() AS caller_company))
  ORDER BY name, (company_id IS NULL);

CREATE OR REPLACE VIEW public.numbering_config_effective WITH (security_invoker = true) AS
 SELECT id,
    floc_prefix,
    floc_pad,
    floc_next,
    equip_prefix,
    equip_pad,
    equip_next,
    auto_number_untagged,
    updated_at,
    company_id
   FROM numbering_config
  WHERE company_id IS NULL OR company_id = (( SELECT caller_company() AS caller_company))
  ORDER BY (company_id IS NULL)
 LIMIT 1;

CREATE OR REPLACE VIEW public.reference_codes_effective WITH (security_invoker = true) AS
 SELECT DISTINCT ON (category, code) id,
    category,
    code,
    description,
    is_locked,
    active,
    properties,
    updated_at,
    category_ref,
    metadata,
    color_code,
    sort_order,
    company_id
   FROM reference_codes
  WHERE company_id IS NULL OR company_id = (( SELECT caller_company() AS caller_company))
  ORDER BY category, code, (company_id IS NULL);

CREATE OR REPLACE VIEW public.sem_asset_reliability WITH (security_invoker = true) AS
 WITH cm AS (
         SELECT w.asset_id,
            count(*) AS failures_12mo,
            COALESCE(sum(w.actual_downtime_hrs), 0::numeric) AS downtime_hrs_12mo,
            count(*) FILTER (WHERE COALESCE(w.actual_downtime_hrs, 0::numeric) > 0::numeric) AS timed_repairs,
            COALESCE(sum(w.actual_downtime_hrs) FILTER (WHERE COALESCE(w.actual_downtime_hrs, 0::numeric) > 0::numeric), 0::numeric) AS timed_downtime_hrs
           FROM work_orders w
          WHERE upper(COALESCE(w.type, ''::text)) = 'CM'::text AND w.created_at >= (now() - '365 days'::interval)
          GROUP BY w.asset_id
        )
 SELECT a.id AS asset_id,
    a.tag AS asset_tag,
    a.criticality::text AS criticality,
    COALESCE(cm.failures_12mo, 0::bigint) AS failures_12mo,
    round(COALESCE(cm.downtime_hrs_12mo, 0::numeric), 1) AS downtime_hrs_12mo,
    GREATEST(0::numeric, 8760::numeric - COALESCE(cm.downtime_hrs_12mo, 0::numeric)) AS operating_hrs_12mo,
        CASE
            WHEN COALESCE(cm.failures_12mo, 0::bigint) > 0 THEN round(GREATEST(0::numeric, 8760::numeric - COALESCE(cm.downtime_hrs_12mo, 0::numeric)) / cm.failures_12mo::numeric, 1)
            ELSE NULL::numeric
        END AS mtbf_hours,
        CASE
            WHEN COALESCE(cm.failures_12mo, 0::bigint) > 0 THEN round(GREATEST(0::numeric, 8760::numeric - COALESCE(cm.downtime_hrs_12mo, 0::numeric)) / cm.failures_12mo::numeric / 24.0, 1)
            ELSE NULL::numeric
        END AS mtbf_days,
        CASE
            WHEN COALESCE(cm.timed_repairs, 0::bigint) > 0 THEN round(cm.timed_downtime_hrs / cm.timed_repairs::numeric, 1)
            ELSE NULL::numeric
        END AS mttr_hours,
        CASE
            WHEN COALESCE(cm.failures_12mo, 0::bigint) > 0 AND COALESCE(cm.timed_repairs, 0::bigint) > 0 THEN round(GREATEST(0::numeric, 8760::numeric - cm.downtime_hrs_12mo) / cm.failures_12mo::numeric / NULLIF(GREATEST(0::numeric, 8760::numeric - cm.downtime_hrs_12mo) / cm.failures_12mo::numeric + cm.timed_downtime_hrs / cm.timed_repairs::numeric, 0::numeric) * 100::numeric, 1)
            ELSE NULL::numeric
        END AS availability_pct,
        CASE
            WHEN COALESCE(cm.failures_12mo, 0::bigint) > 0 THEN round(COALESCE(cm.timed_repairs, 0::bigint)::numeric / cm.failures_12mo::numeric * 100::numeric, 0)
            ELSE 0::numeric
        END AS downtime_coverage_pct
   FROM assets a
     LEFT JOIN cm ON cm.asset_id = a.id;

CREATE OR REPLACE VIEW public.sem_erp_mapping_health WITH (security_invoker = true) AS
 WITH counts AS (
         SELECT 'vendor'::text AS entity_type,
            count(*) AS total
           FROM vendors
        UNION ALL
         SELECT 'cost_center'::text,
            count(*) AS count
           FROM cost_centers
        UNION ALL
         SELECT 'inventory_item'::text,
            count(*) AS count
           FROM inventory_items
        UNION ALL
         SELECT 'work_order'::text,
            count(*) AS count
           FROM work_orders
        UNION ALL
         SELECT 'purchase_order'::text,
            count(*) AS count
           FROM purchase_orders
        UNION ALL
         SELECT 'asset'::text,
            count(*) AS count
           FROM assets
        )
 SELECT c.entity_type,
    c.total AS records,
    COALESCE(m.mapped, 0::bigint) AS mapped,
    c.total - COALESCE(m.mapped, 0::bigint) AS unmapped,
        CASE
            WHEN c.total = 0 THEN 100::numeric
            ELSE round(100.0 * COALESCE(m.mapped, 0::bigint)::numeric / c.total::numeric, 1)
        END AS mapped_pct
   FROM counts c
     LEFT JOIN ( SELECT erp_object_map.entity_type,
            count(*) AS mapped
           FROM erp_object_map
          WHERE erp_object_map.active
          GROUP BY erp_object_map.entity_type) m ON m.entity_type = c.entity_type;

CREATE OR REPLACE VIEW public.sem_failure_events WITH (security_invoker = true) AS
 SELECT wo.id AS work_order_id,
    wo.wo_number,
    wo.title,
    a.id AS asset_id,
    a.tag AS asset_tag,
    a.name AS asset_name,
    a.criticality::text AS criticality,
    wc.code AS work_center_code,
    fd.failure_mode_code,
    fm.description AS failure_mode,
    fd.failure_cause_code,
    fc.description AS failure_cause,
    fd.remedy_code,
    COALESCE(rr.description, rd.description) AS remedy,
    fd.local_impact,
    fd.plant_wide_impact,
    wo.actual_downtime_hrs,
    COALESCE(wo.frozen_labor_cost, 0::numeric) + COALESCE(wo.frozen_material_cost, 0::numeric) AS event_cost,
    wo.created_at AS reported_at,
    wo.closed_at
   FROM work_orders wo
     JOIN wo_failure_data fd ON fd.wo_id = wo.id
     JOIN assets a ON a.id = wo.asset_id
     LEFT JOIN work_centers wc ON wc.id = wo.work_center_id
     LEFT JOIN reference_codes fm ON fm.category = 'FAILURE_MODE'::text AND fm.code = fd.failure_mode_code
     LEFT JOIN reference_codes fc ON fc.category = 'FAILURE_CAUSE'::text AND fc.code = fd.failure_cause_code
     LEFT JOIN reference_codes rr ON rr.category = 'REMEDY_CODE'::text AND rr.code = fd.remedy_code
     LEFT JOIN dictionaries rd ON rd.type = 'REMEDY_CODE'::text AND rd.code = fd.remedy_code;

CREATE OR REPLACE VIEW public.sem_invoice_matches WITH (security_invoker = true) AS
 SELECT m.id AS invoice_id,
    m.company_id,
    m.invoice_number,
    m.invoice_date,
    m.vendor_id,
    v.code AS vendor_code,
    v.name AS vendor_name,
    m.po_id,
    p.po_code,
    m.invoice_amount,
    m.currency,
    m.po_amount,
    m.grn_amount,
    m.variance_amount,
    m.match_status,
    m.payment_block,
    m.payment_date IS NOT NULL AS paid,
    m.matched_at,
    ( SELECT count(*) AS count
           FROM invoice_match_lines l
          WHERE l.invoice_id = m.id) AS lines,
    ( SELECT count(*) AS count
           FROM invoice_match_lines l
          WHERE l.invoice_id = m.id AND l.line_status = 'BLOCKED'::text) AS blocked_lines,
        CASE
            WHEN m.payment_date IS NOT NULL THEN 'paid'::text
            WHEN m.match_status::text = 'BLOCKED'::text THEN 'blocked — '::text || COALESCE(lower(m.payment_block::text), 'variance'::text)
            WHEN m.match_status::text = 'MATCHED'::text THEN 'cleared for payment'::text
            ELSE 'not yet matched'::text
        END AS payables_status
   FROM invoice_matches m
     LEFT JOIN vendors v ON v.id = m.vendor_id
     LEFT JOIN purchase_orders p ON p.id = m.po_id;

CREATE OR REPLACE VIEW public.sem_pm_compliance WITH (security_invoker = true) AS
 SELECT rw.id AS pm_id,
    rw.code,
    rw.title,
    rw.status,
    rw.job_type,
    rw.priority_code,
    rw.schedule_type,
    rw.frequency_interval,
    rw.frequency_unit,
    rw.last_generated_date,
    rw.next_due_date,
    rw.next_due_date IS NOT NULL AND rw.next_due_date < now() AS is_overdue,
    a.id AS asset_id,
    a.tag AS asset_tag,
    a.name AS asset_name,
    a.criticality::text AS criticality,
    wc.code AS work_center_code
   FROM recurring_work rw
     LEFT JOIN assets a ON a.id::text = rw.asset_id
     LEFT JOIN work_centers wc ON wc.id = rw.work_center_id
  WHERE rw.active;

CREATE OR REPLACE VIEW public.sem_purchase_order_lines WITH (security_invoker = true) AS
 SELECT l.id AS line_id,
    l.company_id,
    l.po_id,
    p.po_code,
    p.status AS po_status,
    p.supplier_id,
    v.code AS supplier_code,
    v.name AS supplier_name,
    l.line_no,
    l.line_type,
    l.description,
    l.inventory_id,
    i.part_number,
    i.material_number,
    l.work_order_id,
    w.wo_number,
    l.uom,
    l.qty_ordered,
    l.qty_received,
    GREATEST(l.qty_ordered - l.qty_received, 0::numeric) AS qty_outstanding,
    l.unit_cost,
    l.line_total,
    round(l.qty_received * l.unit_cost, 2) AS received_value,
    l.cost_center_id,
    cc.code AS cost_center_code,
    l.gl_account,
    l.invoice_matched,
    l.created_at,
        CASE
            WHEN l.qty_received <= 0::numeric THEN 'awaiting delivery'::text
            WHEN l.qty_received < l.qty_ordered THEN 'part received'::text
            WHEN l.invoice_matched THEN 'invoiced'::text
            ELSE 'received, awaiting invoice'::text
        END AS line_status
   FROM purchase_order_lines l
     JOIN purchase_orders p ON p.id = l.po_id
     LEFT JOIN vendors v ON v.id = p.supplier_id
     LEFT JOIN inventory_items i ON i.id = l.inventory_id
     LEFT JOIN work_orders w ON w.id = l.work_order_id
     LEFT JOIN cost_centers cc ON cc.id = l.cost_center_id;

CREATE OR REPLACE VIEW public.sem_readings WITH (security_invoker = true) AS
 SELECT rl.id AS reading_id,
    rl.reading_date,
    rl.reading_time,
    rl.reading_value,
    rd.unit,
    rd.name AS reading_name,
    rd.category AS reading_category,
    rd.reading_type_code,
    rd.min_critical,
    rd.min_warning,
    rd.max_warning,
    rd.max_critical,
    rd.monitoring_frequency_days,
    rd.pf_interval_days,
    rl.is_alarm,
        CASE
            WHEN rl.reading_value >= rd.max_critical OR rl.reading_value <= rd.min_critical THEN 'CRITICAL'::text
            WHEN rl.reading_value >= rd.max_warning OR rl.reading_value <= rd.min_warning THEN 'WARNING'::text
            ELSE 'NORMAL'::text
        END AS breach_severity,
    a.id AS asset_id,
    a.tag AS asset_tag,
    a.name AS asset_name,
    a.criticality::text AS criticality,
    rl.entered_by,
    rl.comments,
    rl.created_at
   FROM reading_logs rl
     JOIN reading_definitions rd ON rd.id = rl.definition_id
     JOIN assets a ON a.id = rl.asset_id;

CREATE OR REPLACE VIEW public.sem_specialist_briefing_wo AS
 SELECT id,
    asset_id,
    type,
    status,
    created_at,
    frozen_labor_cost,
    frozen_material_cost,
    total_actual_cost
   FROM work_orders w
  WHERE company_id = (( SELECT caller_company() AS caller_company)) AND ( SELECT caller_can('reliability'::text, 'view'::text) AS caller_can);

CREATE OR REPLACE VIEW public.sem_specialist_overdue_pm AS
 SELECT id,
    asset_id
   FROM recurring_work r
  WHERE company_id = (( SELECT caller_company() AS caller_company)) AND active = true AND next_due_date < now() AND ( SELECT caller_can('reliability'::text, 'view'::text) AS caller_can);

CREATE OR REPLACE VIEW public.sem_stock_movements WITH (security_invoker = true) AS
 SELECT t.id AS movement_id,
    t.company_id,
    t."timestamp" AS moved_at,
    t.movement_type,
    mt.name AS movement_name,
    mt.direction,
    mt.fi_posting,
    t.item_id,
    i.part_number,
    i.material_number,
    t.location_id,
    COALESCE(il.code, il.name) AS location_code,
    t.quantity,
    t.cost_at_time,
    t.total_value,
    t.wo_id,
    w.wo_number,
    t.po_id,
    p.po_code,
    t.cost_center_id,
    cc.code AS cost_center_code,
    t.asset_id,
    a.tag AS asset_tag,
    t.gl_account,
    t.cost_allocation_id,
        CASE
            WHEN mt.fi_posting = 'NONE'::text THEN 'stock only'::text
            WHEN mt.fi_posting = 'VIA_SETTLEMENT'::text THEN 'settles with the order'::text
            WHEN t.cost_allocation_id IS NOT NULL THEN 'posted'::text
            WHEN COALESCE(t.total_value, 0::numeric) = 0::numeric THEN 'no value'::text
            ELSE 'unposted'::text
        END AS fi_status
   FROM inventory_transactions t
     LEFT JOIN movement_types mt ON mt.code = t.movement_type
     LEFT JOIN inventory_items i ON i.id = t.item_id
     LEFT JOIN inventory_locations il ON il.id = t.location_id
     LEFT JOIN work_orders w ON w.id = t.wo_id
     LEFT JOIN purchase_orders p ON p.id = t.po_id
     LEFT JOIN cost_centers cc ON cc.id = t.cost_center_id
     LEFT JOIN assets a ON a.id = t.asset_id;

CREATE OR REPLACE VIEW public.sem_wo_receiver WITH (security_invoker = true) AS
 SELECT w.id AS work_order_id,
    w.asset_id,
    COALESCE(w.cost_center_id, wc.cost_center_id, a.cost_center_id) AS cost_center_id
   FROM work_orders w
     LEFT JOIN work_centers wc ON wc.id = w.work_center_id
     LEFT JOIN assets a ON a.id = w.asset_id;

CREATE OR REPLACE VIEW public.sem_work_history WITH (security_invoker = true) AS
 SELECT wo.id AS work_order_id,
    wo.wo_number,
    wo.title,
    wo.type AS work_type,
    wo.status::text AS status,
    wo.priority_code,
    a.id AS asset_id,
    a.tag AS asset_tag,
    a.name AS asset_name,
    a.criticality::text AS criticality,
    wc.code AS work_center_code,
    wo.recurring_work_id,
    wo.request_id,
    COALESCE(wo.frozen_labor_cost, 0::numeric) AS labor_cost,
    COALESCE(wo.frozen_material_cost, 0::numeric) AS material_cost,
    COALESCE(wo.frozen_labor_cost, 0::numeric) + COALESCE(wo.frozen_material_cost, 0::numeric) AS total_cost,
    wo.actual_downtime_hrs,
    wo.created_at,
    wo.due_date,
    wo.closed_at
   FROM work_orders wo
     JOIN assets a ON a.id = wo.asset_id
     LEFT JOIN work_centers wc ON wc.id = wo.work_center_id;

CREATE OR REPLACE VIEW public.sem_work_orders AS
 SELECT id,
    wo_number,
    title,
    status,
    type,
    priority_code,
    asset_id,
    request_id,
    parent_wo_id,
    cost_frozen,
    frozen_labor_cost,
    frozen_material_cost,
    created_by,
    created_at,
    updated_at,
    closed_at,
    description,
    cost_center,
    due_date,
    date_due_start,
    assigned_to,
    cost_center_id,
    properties,
    total_actual_cost,
    frozen_total_cost,
    reviewed_by,
    reviewed_at,
    review_notes,
    est_duration,
    scope,
    actual_downtime_hrs,
    failure_mode,
    failure_code,
    recurring_work_id,
    warranty_flag,
    warranty_id,
    warranty_claim_id,
    work_center_id,
    import_batch_id,
    ers_wo_state(status::text) AS wo_state,
    ers_wo_state(status::text) = ANY (ARRAY['open'::text, 'unknown'::text]) AS is_open,
    ers_wo_state(status::text) = 'done'::text AS is_done
   FROM work_orders w
  WHERE company_id = (( SELECT caller_company() AS caller_company));

CREATE OR REPLACE VIEW public.tax_codes_effective WITH (security_invoker = true) AS
 SELECT DISTINCT ON (code) id,
    code,
    description,
    tax_type,
    rate,
    jurisdiction,
    applies_to,
    deductible,
    effective_from,
    effective_to,
    active,
    created_at,
    company_id
   FROM tax_codes
  WHERE company_id IS NULL OR company_id = (( SELECT caller_company() AS caller_company))
  ORDER BY code, (company_id IS NULL);

CREATE OR REPLACE VIEW public.vendor_directory AS
 SELECT id,
    name
   FROM vendors
  WHERE company_id = (( SELECT caller_company() AS caller_company));

CREATE OR REPLACE VIEW public.sem_asset_health WITH (security_invoker = true) AS
 SELECT a.id AS asset_id,
    a.tag AS asset_tag,
    a.name AS asset_name,
    a.criticality::text AS criticality,
    a.status_code,
    a.hierarchy_level,
    wc.code AS work_center_code,
    ar.mtbf_days,
    ar.mttr_hours,
    a.failure_count_ytd,
    a.running_hours,
    ow.open_wo_count,
    fe.failure_events_12mo,
    fe.downtime_hrs_12mo,
    pm.overdue_pm_count,
    lr.last_reading_at,
    ar.availability_pct,
    a.mtbf_days AS mtbf_days_stored,
    a.mttr_hours AS mttr_hours_stored
   FROM assets a
     LEFT JOIN work_centers wc ON wc.id = a.responsible_work_center_id
     LEFT JOIN sem_asset_reliability ar ON ar.asset_id = a.id
     LEFT JOIN LATERAL ( SELECT count(*) AS open_wo_count
           FROM work_orders w
          WHERE w.asset_id = a.id AND (ers_wo_state(w.status::text) = ANY (ARRAY['open'::text, 'unknown'::text]))) ow ON true
     LEFT JOIN LATERAL ( SELECT count(*) AS failure_events_12mo,
            COALESCE(sum(w.actual_downtime_hrs), 0::numeric) AS downtime_hrs_12mo
           FROM work_orders w
             JOIN wo_failure_data fd ON fd.wo_id = w.id
          WHERE w.asset_id = a.id AND w.created_at >= (now() - '365 days'::interval)) fe ON true
     LEFT JOIN LATERAL ( SELECT count(*) AS overdue_pm_count
           FROM recurring_work rw
          WHERE rw.asset_id = a.id::text AND rw.active AND rw.next_due_date IS NOT NULL AND rw.next_due_date < now()) pm ON true
     LEFT JOIN LATERAL ( SELECT max(rl.created_at) AS last_reading_at
           FROM reading_logs rl
          WHERE rl.asset_id = a.id) lr ON true;

CREATE OR REPLACE VIEW public.sem_wo_actual_lines WITH (security_invoker = true) AS
 SELECT work_order_id,
    cost_type,
    cost_center_id,
    round(sum(amount), 2) AS amount,
    NULLIF(round(sum(quantity), 3), 0::numeric) AS quantity,
    max(unit) AS unit
   FROM ( SELECT l.wo_id AS work_order_id,
            'LABOR'::text AS cost_type,
            COALESCE(wc.cost_center_id, r.cost_center_id) AS cost_center_id,
            sum(COALESCE(l.hours_worked, 0::numeric) * COALESCE(NULLIF(l.rate_per_hour, 0::numeric), t.planned_rate, wc.activity_rate, 0::numeric)) AS amount,
            sum(COALESCE(l.hours_worked, 0::numeric)) AS quantity,
            'H'::text AS unit
           FROM work_order_labor l
             JOIN job_tasks t ON t.id = l.job_task_id
             JOIN sem_wo_receiver r ON r.work_order_id = l.wo_id
             LEFT JOIN work_centers wc ON wc.id = t.work_center_id
          GROUP BY l.wo_id, (COALESCE(wc.cost_center_id, r.cost_center_id))
        UNION ALL
         SELECT l.wo_id,
            'LABOR'::text AS text,
            r.cost_center_id,
            sum(COALESCE(l.hours_worked, 0::numeric) * COALESCE(l.rate_per_hour, 0::numeric)) AS sum,
            sum(COALESCE(l.hours_worked, 0::numeric)) AS sum,
            'H'::text AS text
           FROM work_order_labor l
             JOIN sem_wo_receiver r ON r.work_order_id = l.wo_id
          WHERE l.job_task_id IS NULL
          GROUP BY l.wo_id, r.cost_center_id
        UNION ALL
         SELECT p.wo_id,
            'MATERIAL'::text AS text,
            r.cost_center_id,
            sum(COALESCE(p.quantity, 0::numeric) * COALESCE(p.unit_cost, 0::numeric)) AS sum,
            NULL::numeric AS "numeric",
            NULL::text AS text
           FROM work_order_parts p
             JOIN sem_wo_receiver r ON r.work_order_id = p.wo_id
          WHERE p.is_planned IS DISTINCT FROM true
          GROUP BY p.wo_id, r.cost_center_id
        UNION ALL
         SELECT pol.work_order_id,
            'SERVICE'::text AS text,
            COALESCE(pol.cost_center_id, r.cost_center_id) AS "coalesce",
            sum(COALESCE(pol.qty_received, 0::numeric) * COALESCE(pol.unit_cost, 0::numeric)) AS sum,
            sum(COALESCE(pol.qty_received, 0::numeric)) AS sum,
            max(pol.uom) AS max
           FROM purchase_order_lines pol
             JOIN sem_wo_receiver r ON r.work_order_id = pol.work_order_id
          WHERE pol.work_order_id IS NOT NULL AND pol.line_type = 'SERVICE'::text AND COALESCE(pol.qty_received, 0::numeric) > 0::numeric
          GROUP BY pol.work_order_id, (COALESCE(pol.cost_center_id, r.cost_center_id))) s
  GROUP BY work_order_id, cost_type, cost_center_id
 HAVING round(sum(amount), 2) <> 0::numeric;

CREATE OR REPLACE VIEW public.sem_wo_settlement WITH (security_invoker = true) AS
 SELECT w.id AS work_order_id,
    w.wo_number,
    w.asset_id,
    ers_wo_state(w.status::text) AS wo_state,
    COALESCE(a.actual_cost, 0::numeric) AS actual_cost,
    COALESCE(p.settled_cost, 0::numeric) AS settled_cost,
    round(COALESCE(a.actual_cost, 0::numeric) - COALESCE(p.settled_cost, 0::numeric), 2) AS unsettled_variance,
    p.last_settled_at
   FROM work_orders w
     LEFT JOIN ( SELECT l.work_order_id,
            sum(l.amount) AS actual_cost
           FROM sem_wo_actual_lines l
          GROUP BY l.work_order_id) a ON a.work_order_id = w.id
     LEFT JOIN ( SELECT c.work_order_id,
            sum(c.amount) AS settled_cost,
            max(c.created_at) AS last_settled_at
           FROM cost_allocations c
          WHERE c.source = 'WO_SETTLEMENT'::text
          GROUP BY c.work_order_id) p ON p.work_order_id = w.id;


-- ══════════════════════════════════════════════
-- Triggers
-- ══════════════════════════════════════════════

DROP TRIGGER IF EXISTS aa_stamp_tenant ON public.asset_bom;
CREATE TRIGGER aa_stamp_tenant BEFORE INSERT ON public.asset_bom FOR EACH ROW EXECUTE FUNCTION stamp_tenant();
DROP TRIGGER IF EXISTS audit_asset_bom_changes ON public.asset_bom;
CREATE TRIGGER audit_asset_bom_changes AFTER INSERT OR DELETE OR UPDATE ON public.asset_bom FOR EACH ROW EXECUTE FUNCTION log_audit_event();
DROP TRIGGER IF EXISTS aa_stamp_tenant ON public.asset_financials;
CREATE TRIGGER aa_stamp_tenant BEFORE INSERT ON public.asset_financials FOR EACH ROW EXECUTE FUNCTION stamp_tenant();
DROP TRIGGER IF EXISTS aa_stamp_tenant ON public.asset_insurance;
CREATE TRIGGER aa_stamp_tenant BEFORE INSERT ON public.asset_insurance FOR EACH ROW EXECUTE FUNCTION stamp_tenant();
DROP TRIGGER IF EXISTS set_updated_at_asset_insurance ON public.asset_insurance;
CREATE TRIGGER set_updated_at_asset_insurance BEFORE UPDATE ON public.asset_insurance FOR EACH ROW EXECUTE FUNCTION update_modified_column();
DROP TRIGGER IF EXISTS aa_stamp_tenant ON public.asset_production_config;
CREATE TRIGGER aa_stamp_tenant BEFORE INSERT ON public.asset_production_config FOR EACH ROW EXECUTE FUNCTION stamp_tenant();
DROP TRIGGER IF EXISTS aa_stamp_tenant ON public.assets;
CREATE TRIGGER aa_stamp_tenant BEFORE INSERT ON public.assets FOR EACH ROW EXECUTE FUNCTION stamp_tenant();
DROP TRIGGER IF EXISTS audit_assets_changes ON public.assets;
CREATE TRIGGER audit_assets_changes AFTER INSERT OR DELETE OR UPDATE ON public.assets FOR EACH ROW EXECUTE FUNCTION log_audit_event();
DROP TRIGGER IF EXISTS auto_equipment_number ON public.assets;
CREATE TRIGGER auto_equipment_number BEFORE INSERT ON public.assets FOR EACH ROW EXECUTE FUNCTION generate_equipment_number();
DROP TRIGGER IF EXISTS aa_stamp_tenant ON public.audit_assessment_collaborators;
CREATE TRIGGER aa_stamp_tenant BEFORE INSERT ON public.audit_assessment_collaborators FOR EACH ROW EXECUTE FUNCTION stamp_tenant();
DROP TRIGGER IF EXISTS aa_stamp_tenant ON public.audit_assessments;
CREATE TRIGGER aa_stamp_tenant BEFORE INSERT ON public.audit_assessments FOR EACH ROW EXECUTE FUNCTION stamp_tenant();
DROP TRIGGER IF EXISTS audit_assessments_changes ON public.audit_assessments;
CREATE TRIGGER audit_assessments_changes AFTER INSERT OR DELETE OR UPDATE ON public.audit_assessments FOR EACH ROW EXECUTE FUNCTION log_audit_event();
DROP TRIGGER IF EXISTS aa_stamp_tenant ON public.audit_corrective_actions;
CREATE TRIGGER aa_stamp_tenant BEFORE INSERT ON public.audit_corrective_actions FOR EACH ROW EXECUTE FUNCTION stamp_tenant();
